{"command":"cat > main.py << 'PYEOF'
#!/usr/bin/env python3
import os, sys, re, time, signal, stat, struct, math, threading
from dataclasses import dataclass, field

VERSION = "1.14.0.git"

# ---------- output helpers ----------
def encode_bytes(s):
    if isinstance(s, bytes):
        return s
    return os.fsencode(s)
def out_write(s):
    data = encode_bytes(s)
    try:
        os.write(1, data)
    except BrokenPipeError:
        raise
def err_write(s):
    data = encode_bytes(s)
    try:
        os.write(2, data)
    except BrokenPipeError:
        pass
def print_out(s=""):
    out_write(s if (isinstance(s, bytes) or s.endswith("\n")) else s+"\n")
def print_err(s=""):
    err_write(s if (isinstance(s, bytes) or s.endswith("\n")) else s+"\n")

class FatalError(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg
class NinjaError(Exception):
    """Error whose msg is printed after 'ninja: error: '"""
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg

def Fatal(msg):
    raise FatalError(msg)
def Error(msg):
    err_write(f"ninja: error: {msg}\n")
def Warning(msg):
    err_write(f"ninja: warning: {msg}\n")

# globals for debug
g_explain = False
g_keeprsp = False
g_keepdepfile = False
g_stats = False
g_phonycycle_err = False

def EXPLAIN(fmt, *args):
    if g_explain:
        err_write("ninja explain: " + (fmt % args if args else fmt) + "\n")

# ---------- metrics ----------
METRIC_NAMES = [".ninja parse", ".ninja_log load", ".ninja_deps load", "node stat", "depfile load", "ComputeCriticalPath", "StartEdge", "FinishCommand"]
class Metrics:
    def __init__(self):
        self.data = {n:[0,0.0] for n in METRIC_NAMES}  # count, total microseconds
    def record(self, name, elapsed_us):
        if not g_stats:
            return
        m = self.data.setdefault(name, [0,0.0])
        m[0] += 1; m[1] += float(elapsed_us)
class MetricTimer:
    def __init__(self, metrics, name):
        self.metrics=metrics; self.name=name; self.start=0
    def __enter__(self):
        self.start=time.perf_counter_ns(); return self
    def __exit__(self,*a):
        if g_stats:
            self.metrics.record(self.name, (time.perf_counter_ns()-self.start)/1000.0)
        return False
g_metrics = Metrics()

# ---------- utilities ----------
def strerror_of(e):
    if isinstance(e, OSError):
        return e.strerror or str(e)
    return str(e)

def canonicalize_path(path):
    if path == "":
        return ""
    is_abs = path.startswith("/")
    parts=[]
    for comp in path.split("/"):
        if comp == "" or comp == ".":
            continue
        if comp == "..":
            if parts and parts[-1] != "..":
                parts.pop()
            elif not is_abs:
                parts.append(comp)
            # absolute: skip
        else:
            parts.append(comp)
    if is_abs:
        return "/" + "/".join(parts) if parts else "/"
    else:
        return "/".join(parts) if parts else "."

SHELL_SAFE = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_+-./")
def shell_escape(s):
    if s and all(c in SHELL_SAFE for c in s):
        return s
    if s == "":
        return "''"
    return "'" + s.replace("'", "'\\''") + "'"

def edit_distance(a,b):
    la, lb=len(a), len(b)
    if la==0: return lb
    if lb==0: return la
    prev=list(range(lb+1))
    for i,ca in enumerate(a,1):
        cur=[i]+[0]*lb
        for j,cb in enumerate(b,1):
            cur[j]=min(prev[j]+1, cur[j-1]+1, prev[j-1]+(0 if ca==cb else 1))
        prev=cur
