    outs=[]; ins=[]
    i=0; n=len(content)
    target_mode=True
    seen_any_rule=False
    current_outs=0
    at_line_start=True
    completed_rule=False
    while i<n:
        # skip spaces/tabs but note line starts
        if content[i] in " \t\r":
            i+=1; continue
        if content[i]=="\n":
            if target_mode:
                if current_outs>0 and not completed_rule:
                    raise NinjaError("expected ':' in depfile")
                if current_outs>0 and completed_rule:
                    # pending incomplete rule on a line: if more non-empty content follows, error; else ignore
                    rest=content[i+1:].strip()
                    if rest:
                        raise NinjaError("expected ':' in depfile")
                    i+=1; break
                i+=1; at_line_start=True; continue
            else:
                target_mode=True; current_outs=0; completed_rule=True; i+=1; at_line_start=True; continue
        if at_line_start and completed_rule and target_mode and content[i]!="\n":
            # A line starting with whitespace was already skipped above; distinguishing is hard.
            pass
        # colon separator
        if content[i]==":":
            if target_mode:
                target_mode=False; seen_any_rule=True; i+=1; at_line_start=False; continue
            else:
                i+=1; continue
        # parse word
        word=[]; ended_by_colon=False
        while i<n:
            ch=content[i]
            if ch in " \t\r\n\x0b\x0c":
                break
            if ch=="\\":
                if i+1<n and content[i+1] in "\n\r":
                    # line continuation: consume slash and newline (and CRLF)
                    i+=1
                    if i<n and content[i]=="\r": i+=1
                    if i<n and content[i]=="\n": i+=1
                    break
                elif i+1<n:
                    word.append(content[i+1]); i+=2; continue
                else:
                    i+=1; break
            if ch=="$":
                if i+1<n and content[i+1]!="\n":
                    word.append(content[i+1]); i+=2; continue
                else:
                    i+=1; break
            if ch==":":
                if target_mode:
                    ended_by_colon=True; break
                # deps mode: colon followed by whitespace/eof means this word is a new target
                nxt=content[i+1] if i+1<n else ""
                if nxt=="" or nxt in " \t\r\n":
                    ended_by_colon=True; break
                word.append(ch); i+=1; continue
            # '#' is treated as ordinary char here (escaped in real depfiles)
            word.append(ch); i+=1
        w="".join(word)
        at_line_start=False
        if w:
            if target_mode:
                outs.append(w); current_outs+=1
            else:
                if ended_by_colon:
                    outs.append(w)
                    # next loop will see colon in ... but we are in deps mode; switch to a new rule's deps after colon
                    # Mark that following colon should keep deps mode; we implement by staying in deps mode (colon skipped above)
                else:
                    ins.append(w)
        if ended_by_colon and target_mode:
            # consume colon
            if i<n and content[i]==":":
                i+=1; target_mode=False; seen_any_rule=True
        elif ended_by_colon and not target_mode:
            if i<n and content[i]==":":
                i+=1
                # remain in deps mode for new rule
    if target_mode and current_outs>0 and not completed_rule:
        raise NinjaError("expected ':' in depfile")
    return outs,ins

