        self.load_err=""
    def load(self,path):
        with MetricTimer(g_metrics,".ninja_log load"):
            self.path=path
            status,content,err=Disk.read_file(path)
            if status=="notfound":
                self.load_status="notfound"; self.file_needs_header=True; return True
            if status!="ok":
                self.load_status="error"; self.load_err=f"loading build log {path}: {err}"; return False
            if content=="":
                self.load_status="ok"; self.file_needs_header=True; return True
            lines=content.split("\n")
            first=lines[0] if lines else ""
            m=re.match(r"# ninja log v\s*([+-]?\d+)",first)
            version=0
            if m:
                try:
                    v=int(m.group(1)) & 0xffffffff
                    if v>=0x80000000: v-=0x100000000
                    version=v
                except: version=0
            if version<7:
                self.load_status="old"; return True
            if version>7:
                self.load_status="new"; return True
            self.load_status="ok"
            # entries lines[1:]
            body=lines[1:]
            for line in body:
                if line.endswith("\r"): line=line[:-1]
                parts=line.split("\t")
                if len(parts)<5: continue
                try:
                    start=c_atoi(parts[0]); end=c_atoi(parts[1])
                    mv,cons=parse_c_long(parts[2]); mtime=mv
                    output=parts[3]
                    hv=parts[4]
                    # strtoull base16
                    hv=hv.strip() if False else hv
                    # parse leading hex
                    mm=re.match(r"\s*(?:0[xX])?([0-9a-fA-F]+)",hv)
                    h=int(mm.group(1),16) if mm else 0
                    h &= (1<<64)-1
                except Exception:
                    continue
                if output in self.entries:
                    e=self.entries[output]; e.start=start; e.end=end; e.mtime=mtime; e.hash=h
                else:
                    self.entries[output]=LogEntry(start,end,mtime,output,h)
            self.file_needs_header=False
            return True
    def lookup(self,output):
        return self.entries.get(output)
    def open_for_write(self):
        if self.file is not None: return (True,"")
        try:
            needs_header=self.file_needs_header
            if not needs_header:
                try:
                    if os.path.getsize(self.path)==0: needs_header=True
                except OSError:
