        try:
            for out in edge.outputs:
                line=f"{start_ms}\t{end_ms}\t{record_mtime}\t{out.path}\t{command_hash:x}\n"
                self.file.write(encode_bytes(line))
                if out.path in self.entries:
                    e=self.entries[out.path]; e.start=start_ms; e.end=end_ms; e.mtime=record_mtime; e.hash=command_hash
                else:
                    self.entries[out.path]=LogEntry(start_ms,end_ms,record_mtime,out.path,command_hash)
