class DepsLog:
    def __init__(self,state):
        self.state=state
        self.nodes=[]  # Node in id order
        self.node_ids={} # id(node)?? use path->id via node object index in list; map node->id by path
        self.path_to_id={}
        self.deps={} # output Node -> DepsEntry (key by node path)
        self.deps_by_path={}
        self.path=""
        self.file=None
        self.load_status="notfound" # ok, notfound, bad, premature
        self.truncate_offset=None
        self.total_records=0
    def load(self,path):
        with MetricTimer(g_metrics,".ninja_deps load"):
            self.path=path
            try:
                with open(path,"rb") as f: data=f.read()
            except FileNotFoundError:
                self.load_status="notfound"; return True
            except OSError:
                # treated as bad signature (reference: directory gives bad)
                self.load_status="bad"; return True
            if len(data)<16 or not data.startswith(b"# ninjadeps\n"):
                self.load_status="bad"; return True
            version=struct.unpack_from("<i",data,12)[0]
            if version!=4:
                self.load_status="bad"; return True
            ofs=16; valid_end=ofs
            self.load_status="ok"
            while ofs<len(data):
                rec_start=ofs
                if len(data)-ofs<4:
                    # partial size: reference appears to ignore 1 byte case; treat as ok break
                    break
                size_raw=struct.unpack_from("<I",data,ofs)[0]; ofs+=4
                is_deps = bool(size_raw & 0x80000000)
                size=size_raw & 0x7fffffff
                if size<0 or ofs+size>len(data):
                    self.load_status="premature"; self.truncate_offset=valid_end; break
                payload=data[ofs:ofs+size]; ofs+=size
                if not is_deps:
                    if size<4:
                        self.load_status="bad"; return True
                    checksum=struct.unpack_from("<i",payload,size-4)[0]
                    expected=-(len(self.nodes))-1
                    if checksum!=expected:
                        self.load_status="bad"; return True
                    path_bytes=payload[:size-4]
                    nul=path_bytes.find(b"\x00")
                    if nul!=-1: path_bytes=path_bytes[:nul]
                    p=path_bytes.decode('utf-8','surrogateescape')
                    node=self.state.get_node(canonicalize_path(p) if p else p)
                    self.path_to_id[node.path]=len(self.nodes)
                    self.nodes.append(node)
                else:
                    if size<12 or size%4!=0:
                        self.load_status="bad"; return True
                    out_id=struct.unpack_from("<i",payload,0)[0]
                    mtime=struct.unpack_from("<q",payload,4)[0]
                    dep_ids=[]
                    bad=False
                    for j in range(12,size,4):
                        did=struct.unpack_from("<i",payload,j)[0]
                        if did<0 or did>=len(self.nodes): bad=True; break
                        dep_ids.append(did)
                    if bad or out_id<0 or out_id>=len(self.nodes):
                        self.load_status="bad"; return True
                    out_node=self.nodes[out_id]
                    deps=[self.nodes[d] for d in dep_ids]
                    self.deps_by_path[out_node.path]=DepsEntry(mtime,deps)
                    self.total_records+=1
                valid_end=ofs
            return True
    def get_deps(self,node):
        return self.deps_by_path.get(node.path)
    def open_for_write(self):
        if self.file is not None: return (True,"")
        try:
            needs_header=False
            try:
                if os.path.getsize(self.path)==0: needs_header=True
            except OSError:
                needs_header=True
            if self.load_status in ("notfound","bad"):
                needs_header=True
            f=open(self.path,"ab")
            self.file=f
            if needs_header:
                f.write(b"# ninjadeps\n"+struct.pack("<i",4)); f.flush()
            return (True,"")
        except OSError as e:
            return (False, e.strerror or str(e))
    def _ensure_id(self,node):
        if node.path in self.path_to_id:
            return (self.path_to_id[node.path],True)
        # write path record
        nid=len(self.nodes)
        ok,err=self.open_for_write()
        if not ok: return (-1,False)
        pb=encode_bytes(node.path)
        padded_len=((len(pb)+3)//4)*4
        rec_size=padded_len+4
        try:
            self.file.write(struct.pack("<I",rec_size))
            self.file.write(pb); self.file.write(b"\x00"*(padded_len-len(pb)))
            self.file.write(struct.pack("<i",-nid-1))
        except OSError:
            return (-1,False)
        self.path_to_id[node.path]=nid; self.nodes.append(node)
        return (nid,True)
    def record_deps(self,node,mtime,deps):
        # deps list of Node
        existing=self.deps_by_path.get(node.path)
        if existing is not None and existing.mtime==mtime and [d.path for d in existing.deps]==[d.path for d in deps]:
            return (True,"")
        out_id,ok=self._ensure_id(node)
        if not ok: return (False,"Error writing to deps log: Unable to write")
        dep_ids=[]
        for d in deps:
            did,ok=self._ensure_id(d)
            if not ok: return (False,"Error writing to deps log: Unable to write")
            dep_ids.append(did)
        ok,err=self.open_for_write()
        if not ok: return (False,f"Error writing to deps log: {err}")
        size=4+8+4*len(dep_ids)
        try:
            self.file.write(struct.pack("<I",size|0x80000000))
            self.file.write(struct.pack("<i",out_id)); self.file.write(struct.pack("<q",mtime))
            for did in dep_ids: self.file.write(struct.pack("<i",did))
            self.file.flush()
        except OSError as e:
            return (False,f"Error writing to deps log: {e.strerror or str(e)}")
        self.deps_by_path[node.path]=DepsEntry(mtime,list(deps))
        self.total_records+=1
        return (True,"")
    def close(self):
        if self.file:
            try: self.file.close()
            except Exception: pass
            self.file=None
    def recompact(self,path,live_output_paths):
        temp=path+".recompact"
        try:
            f=open(temp,"wb")
        except OSError as e:
            return (False, e.strerror or str(e))
        new_ids={}; new_nodes=[]
        def ensure(node):
            if node.path in new_ids: return new_ids[node.path]
            nid=len(new_nodes); new_ids[node.path]=nid; new_nodes.append(node)
            pb=encode_bytes(node.path); padded=((len(pb)+3)//4)*4
            f.write(struct.pack("<I",padded+4)); f.write(pb); f.write(b"\x00"*(padded-len(pb))); f.write(struct.pack("<i",-nid-1))
            return nid
        try:
            f.write(b"# ninjadeps\n"+struct.pack("<i",4))
            # iterate in old node id order for outputs that are live and have deps
            for node in list(self.nodes):
                entry=self.deps_by_path.get(node.path)
                if entry is None: continue
                if node.path not in live_output_paths: continue
                out_id=ensure(node)
                dep_ids=[ensure(d) for d in entry.deps]
                size=12+4*len(dep_ids)
                f.write(struct.pack("<I",size|0x80000000)); f.write(struct.pack("<i",out_id)); f.write(struct.pack("<q",entry.mtime))
                for did in dep_ids: f.write(struct.pack("<i",did))
            f.close()
        except OSError as e:
            try: f.close()
            except Exception: pass
            return (False, e.strerror or str(e))
        try:
            os.remove(path)
        except OSError as e:
            return (False, e.strerror or str(e))
        try:
            os.rename(temp,path)
        except OSError as e:
            return (False, e.strerror or str(e))
        # rebuild internal structures to new ids (reload from file would be simplest, but keep)
        self.nodes=new_nodes; self.path_to_id=dict(new_ids)
        return (True,"")

