                    mtime=struct.unpack_from("<q",payload,4)[0]
                    dep_ids=[]
                    bad=False
                    for j in range(12,size,4):
                        did=struct.unpack_from("<i",payload,j)[0]
                        if did<0 or did>=len(self.nodes): bad=True; break
                        dep_ids.append(did)
                    if bad or out_id<0 or out_id>=len(self.nodes):
                        self.load_status="bad"; return True
                    out_node=self.nodes[out_id]
                    deps=[self.nodes[d] for d in dep_ids]
