            lexer.error("expected 'ninja_dyndep_version = ...'", pos=t.start, line=t.line, show=False)
        if t.value=="build" or t.value in ("rule","pool","default","include","subninja"):
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=t.start, line=t.line, show=False)
        name=t.value
