        ev,line,nlpos=lexer.read_eval_string("value", equals_pos=eq.start)
        val=ev.evaluate(dummy_env)
        if name!="ninja_dyndep_version":
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=nlpos, line=line)
