        if node in self.visiting:
            idx=self.visiting.index(node)
            cycle=[n.path for n in self.visiting[idx:]]+[node.path]
            raise NinjaError("dependency cycle: " + " -> ".join(cycle))
        node.stat_if_necessary()
        edge=node.in_edge
        if edge is None:
            node.dirty=False; node.status_known=True; return
        if validation_nodes is not None:
            for v in edge.validations:
                if v not in validation_nodes:
                    validation_nodes.append(v)
        if edge.scan_evaluated:
            # output dirty already derived
            return
        self.visiting.append(node)
        try:
            # dyndep: first visit dyndep node if it is an input to determine pending.
            # We visit static inputs first (below) but need dyndep load before evaluating new inputs.
            # Approach: if dyndep node exists, visit it now.
            dyndep_pending=False
            if edge.dyndep_node is not None and not edge.dyndep_loaded:
                dn=edge.dyndep_node
                if dn is not node and dn not in self.visiting:
                    # visit dyndep node (its edge may be ...), ignore validation collection duplication handled
                    self._visit(dn, validation_nodes)
                # now try load
                try:
                    loaded=self.load_dyndeps_for_edge(edge)
                except NinjaError:
                    raise
                if not loaded:
                    dyndep_pending=True
            # Visit static inputs (including possibly new dyndep inputs)
            for inp in list(edge.inputs):
                self._visit(inp, validation_nodes)
            # depfile/deps loading (may explain missing)
            deps_dirty=False
            if not dyndep_pending:
                deps_dirty=self.load_deps_for_edge(edge,node)
                # visit dep nodes
                for depnode in list(edge.dep_nodes):
                    self._visit(depnode, None)
            else:
                deps_dirty=False
            # Determine dirty
            # Most recent non-order input
            most_recent=None; most_recent_mtime=0
            def consider(inp):
                nonlocal most_recent,most_recent_mtime
                mt=inp.stat_if_necessary()
                if mt>most_recent_mtime:
                    most_recent_mtime=mt; most_recent=inp
            non_order_inputs=[]
            oo=set(id(x) for x in edge.order_only_inputs())
            # inputs order explicit/implicit then dep nodes; order-only excluded
            for inp in edge.inputs:
                if id(inp) in oo and inp in edge.order_only_inputs():
                    continue
                non_order_inputs.append(inp)
            # Above check by identity via slice positions is safer:
            non_order_inputs=edge.inputs[:len(edge.inputs)-edge.order_only_in] if edge.order_only_in else list(edge.inputs)
            for inp in non_order_inputs: consider(inp)
            for inp in edge.dep_nodes: consider(inp)
            any_input_dirty=False
            for inp in non_order_inputs:
                if inp.dirty:
                    EXPLAIN("%s is dirty", inp.path); any_input_dirty=True
            for inp in edge.dep_nodes:
                if inp.dirty:
                    # reference prints "<dep> is dirty" in some cases (hdr removed)
                    EXPLAIN("%s is dirty", inp.path); any_input_dirty=True
            if dyndep_pending:
                # Output cannot be determined clean yet; mark all outputs dirty (conservatively for plan pending)
                for out in edge.outputs:
                    out.dirty=True; out.status_known=True
                edge.scan_evaluated=False  # allow re-evaluation after dyndep loads; but status_known would block.
                # To allow re-evaluation, clear status_known for outputs? Builder will reset before re-scan.
                # Keep status known for this scan to make plan include as pending.
                return
            # command hash computed once if needed (non-phony and build log present)
            command_hash=None
            if not edge.is_phony() and self.build_log is not None:
                # Only compute if any output exists (to avoid fatal cycles on missing? reference computes for missing too in some paths?)
                # We compute lazily per output check below.
                pass
            for out in edge.outputs:
                out.dirty=self._recompute_output_dirty(edge,out,most_recent,most_recent_mtime,deps_dirty,any_input_dirty)
                out.status_known=True
            edge.scan_evaluated=True
        finally:
            if node in self.visiting:
                self.visiting.remove(node)
    def _recompute_output_dirty(self,edge,out,most_recent,most_recent_mtime,deps_dirty,any_input_dirty):
        if deps_dirty:
            return True
        if edge.is_phony():
            if any_input_dirty: return True
            if out.stat_if_necessary()==0: return True
            if most_recent is not None and most_recent_mtime>out.mtime: return True
            return False
        # If any input dirty, still check command etc for explain of command changes, but outcome true.
        # Missing output: explain only if not any_input_dirty (matches observed)
        if out.stat_if_necessary()==0:
            if not any_input_dirty:
                EXPLAIN("output %s doesn't exist", out.path)
            return True
        if most_recent is not None and out.mtime < most_recent_mtime:
            EXPLAIN("output %s older than most recent input %s (%s vs %s)", out.path, most_recent.path, out.mtime, most_recent_mtime)
            return True
        if self.build_log is not None:
            entry=self.build_log.lookup(out.path)
            is_generator=edge.get_binding_bool("generator")
            if entry is None:
                if not is_generator:
                    EXPLAIN("command line not found in log for %s", out.path)
                    return True
            else:
                if not is_generator:
                    h=edge.evaluate_command_hash()
                    if h!=entry.hash:
                        EXPLAIN("command line changed for %s", out.path)
                        return True
                    if most_recent is not None and entry.mtime < most_recent_mtime:
                        EXPLAIN("recorded mtime of %s older than most recent input %s (%s vs %s)", out.path, most_recent.path, entry.mtime, most_recent_mtime)
                        return True
        if any_input_dirty:
            return True
        return False

PYEOF
"}

