# ---------- dyndep ----------
class DyndepStatement:
    def __init__(self,out_node,imp_outs,imp_ins,restat):
        self.out=out_node; self.imp_outs=imp_outs; self.imp_ins=imp_ins; self.restat=restat

class DyndepParser:
    def __init__(self,state,filename,content,manifest_parser):
        self.state=state; self.lexer=Lexer(filename,content,manifest_parser); self.filename=filename
        self.parser=manifest_parser
    def parse(self, recipient_edges):
        # returns list of DyndepStatement; raises ParseError or NinjaError(msg)
        lexer=self.lexer
        # version line: skip newlines/comments? Lexer ReadToken skips comments.
        # Need parse an assignment manually.
        # Use tokens: expect ident
        # Blank file: first token EOF -> expected version blank
        # We need special handling to mirror messages.
        while True:
            t=lexer.read_token()
            if t.typ=="NEWLINE": continue
            break
        if t.typ!="IDENT":
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=t.start, line=t.line, show=False)
        if t.value=="build" or t.value in ("rule","pool","default","include","subninja"):
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=t.start, line=t.line, show=False)
        name=t.value
        eq=lexer.read_token()
        if eq.typ!="EQUALS":
            got=TOKEN_DESCR.get(eq.typ,eq.typ)
            lexer.error(f"expected '=', got {got}", pos=eq.start, line=eq.line)
        lexer.eat_whitespace()
        dummy_env=BindingEnv()
        ev,line,nlpos=lexer.read_eval_string("value", equals_pos=eq.start)
        val=ev.evaluate(dummy_env)
        if name!="ninja_dyndep_version":
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=nlpos, line=line)
        # parse version numeric major/minor from val
        major=0; minor=0
        m=re.match(r"\s*(\d+)",val)
        if m:
            major=int(m.group(1)); rest=val[m.end():]
            if rest.startswith("."):
                m2=re.match(r"(\d+)",rest[1:])
                if m2: minor=int(m2.group(1))
        if not (major==1 and minor==0):
            lexer.error(f"unsupported 'ninja_dyndep_version = {val}'", pos=nlpos, line=line)
        # map output path -> edge (any output of recipient edges)
        out_to_edge={}
        for e in recipient_edges:
            for o in e.outputs:
                out_to_edge[o.path]=e
        statements=[]; seen_out_paths=set()
        seen_edges=set()
        while True:
            t=lexer.read_token()
            if t.typ=="EOF": break
            if t.typ=="NEWLINE": continue
            if t.typ=="IDENT":
                if t.value=="build":
                    stmt=self.parse_build_statement(out_to_edge, seen_out_paths)
                    statements.append(stmt)
                    continue
                elif t.value in ("rule","pool","default","include","subninja"):
                    lexer.error(f"unexpected '{t.value}'", pos=t.start, line=t.line, show=False)
                else:
                    lexer.error("unexpected identifier", pos=t.start, line=t.line, show=False)
            elif t.typ=="INDENT":
                lexer.error("unexpected indent", pos=t.start, line=t.line, show=False)
            elif t.typ=="ERROR":
                lexer.error(t.value, pos=t.start, line=t.line, show=False)
            else:
                val=t.value if t.value else t.typ
                lexer.error(f"unexpected '{val}'", pos=t.start, line=t.line, show=False)
        # check all recipient edges mentioned: For each edge, at least one statement for one of its outputs?
        # Reference expects a statement for each build statement (edge). Use first output in error if missing.
        mentioned_edges=set()
        for s in statements:
            e=out_to_edge.get(s.out.path)
            if e is not None: mentioned_edges.add(id(e))
        for e in recipient_edges:
            if id(e) not in mentioned_edges:
                first=e.outputs[0].path if e.outputs else ""
                raise NinjaError(f"'{first}' not mentioned in its dyndep file '{self.filename}'")
        return statements
    def parse_build_statement(self,out_to_edge,seen_out_paths):
        lexer=self.lexer
        # outputs
        outputs=[]; imp_outs=[]
        while True:
            ev=lexer.read_path()
            if ev.empty(): break
            val=ev.evaluate(BindingEnv())
            if val=="":
                raise ParseError(f"{self.filename}:{lexer.line_number}: empty path\n\n")
            outputs.append(canonicalize_path(val))
        # implicit outs
        if lexer.ofs<lexer.len and lexer.content[lexer.ofs]=="|":
            nxt=lexer.content[lexer.ofs+1] if lexer.ofs+1<lexer.len else ""
            if nxt not in "|@":
                lexer.ofs+=1
                while True:
                    ev=lexer.read_path()
                    if ev.empty(): break
                    imp_outs.append(canonicalize_path(ev.evaluate(BindingEnv())))
        colon_pos=lexer.ofs
        if not outputs and not imp_outs:
            lexer.error("expected path", pos=lexer.ofs, line=lexer.line_number)
        if len(outputs)>1:
            lexer.error("explicit outputs not supported", pos=colon_pos, line=lexer.line_number)
        if not outputs:
            # only implicit outputs: explicit outputs count 0 - treat first implicit? reference likely explicit not supported? Use expected path
            lexer.error("explicit outputs not supported", pos=colon_pos, line=lexer.line_number)
        # check existence / duplicates at colon position (reference)
        out_path=outputs[0]
        if out_path in seen_out_paths:
            lexer.error(f"multiple statements for '{out_path}'", pos=colon_pos, line=lexer.line_number)
        seen_out_paths.add(out_path)
        if out_path not in out_to_edge:
            lexer.error(f"no build statement exists for '{out_path}'", pos=colon_pos, line=lexer.line_number)
        t=lexer.read_token()
        if t.typ!="COLON":
            got=TOKEN_DESCR.get(t.typ,t.typ)
            lexer.error(f"expected ':', got {got} ($ also escapes ':')", pos=t.start, line=t.line)
        rt=lexer.read_token()
        if rt.typ!="IDENT" or rt.value!="dyndep":
            lexer.error("expected build command name 'dyndep'", pos=rt.start, line=rt.line)
        # inputs: explicit (not allowed), implicit, order (not allowed)
        explicit=[]; implicit=[]; order=[]
        seg=0
        order_pos=None
        while True:
            lexer.skip_spaces_tabs()
            if lexer.ofs>=lexer.len:
                lexer.error("unexpected EOF", pos=lexer.ofs, line=lexer.line_number)
            ch=lexer.content[lexer.ofs]
            if ch=="\n":
                nl_line=lexer.line_number; nl_pos=lexer.ofs
                lexer.ofs+=1; lexer.line_number+=1; lexer.line_start=True; break
            if ch=="|":
                if lexer.ofs+1<lexer.len and lexer.content[lexer.ofs+1]=="|":
                    if seg>=2:
                        lexer.error("expected newline, got '||'", pos=lexer.ofs, line=lexer.line_number)
                    seg=2; order_pos=lexer.ofs; lexer.ofs+=2; continue
                elif lexer.ofs+1<lexer.len and lexer.content[lexer.ofs+1]=="@":
                    lexer.error("expected newline, got '|@'", pos=lexer.ofs, line=lexer.line_number)
                else:
                    if seg>=1:
                        lexer.error("expected newline, got '|'", pos=lexer.ofs, line=lexer.line_number)
                    seg=1; lexer.ofs+=1; continue
            if ch==":":
                lexer.error("expected newline, got ':'", pos=lexer.ofs, line=lexer.line_number)
            ev=lexer.read_path()
            if ev.empty():
                t=lexer.read_token(); got=TOKEN_DESCR.get(t.typ,t.typ)
                lexer.error(f"expected newline, got {got}", pos=t.start, line=t.line)
            val=ev.evaluate(BindingEnv()); p=canonicalize_path(val)
            if seg==0: explicit.append(p)
            elif seg==1: implicit.append(p)
            else: order.append(p)
        if explicit:
            lexer.error("explicit inputs not supported", pos=nl_pos, line=nl_line)
        if order:
            lexer.error("order-only inputs not supported", pos=order_pos, line=nl_line)
        # bindings: restat only
        restat=False
        while True:
            pt=lexer.peek_token()
            if pt.typ!="INDENT": break
            lexer.read_token()
            # indented assignment
            tt=lexer.read_token()
            if tt.typ!="IDENT":
                lexer.error("expected variable name", pos=tt.start, line=tt.line)
            key=tt.value
            eq=lexer.read_token()
            if eq.typ!="EQUALS":
                got=TOKEN_DESCR.get(eq.typ,eq.typ)
                lexer.error(f"expected '=', got {got}", pos=eq.start, line=eq.line)
            lexer.eat_whitespace()
            ev,line2,nlp=lexer.read_eval_string("value", equals_pos=eq.start)
            if key!="restat":
                lexer.error("binding is not 'restat'", pos=nlp, line=line2)
            if ev.evaluate(BindingEnv())!="":
                restat=True
            else:
                restat=False
        edge=out_to_edge[out_path]
        out_node=self.state.get_node(out_path)
        imp_out_nodes=[self.state.get_node(canonicalize_path(p)) for p in imp_outs]
        imp_in_nodes=[self.state.get_node(canonicalize_path(p)) for p in implicit]
        return DyndepStatement(out_node,imp_out_nodes,imp_in_nodes,restat)

def load_dyndep_file(state, dyndep_path, recipient_edges, manifest_parser):
    # returns statements; raises NinjaError with full message body (without ninja: prefix handling by caller contexts)
    # Increase .ninja parse metric inside DyndepParser? Reference counts as .ninja parse
    with MetricTimer(g_metrics,".ninja parse"):
        status,content,err=Disk.read_file(dyndep_path)
        if status!="ok":
            raise NinjaError(f"loading '{dyndep_path}': {err}")
        parser=DyndepParser(state,dyndep_path,content,manifest_parser)
        return parser.parse(recipient_edges)

def apply_dyndep_statements(state, statements, recipient_edges):
    out_to_edge={}
    for e in recipient_edges:
        for o in e.outputs: out_to_edge[o.path]=e
    for s in statements:
        edge=out_to_edge[s.out.path]
        # implicit outputs
        for node in s.imp_outs:
            if node.in_edge is not None and node.in_edge is not edge:
                raise NinjaError(f"multiple rules generate {node.path}")
            if node not in edge.outputs:
                edge.outputs.append(node); edge.implicit_out+=1; node.in_edge=edge
        # implicit inputs: insert before order-only
        insert_at=len(edge.inputs)-edge.order_only_in
        for node in s.imp_ins:
            # check duplicate static input? original adds even if duplicate likely
            edge.inputs.insert(insert_at,node); insert_at+=1; edge.implicit_in+=1
            node.out_edges.append(edge)
        if s.restat:
            edge.restat_dyndep=True
        edge.dyndep_loaded=True; edge.dyndep_pending=False
    for e in recipient_edges:
        e.dyndep_loaded=True; e.dyndep_pending=False

# ---------- dependency scan ----------
class DependencyScan:
    def __init__(self,state,build_log,deps_log,manifest_parser):
        self.state=state; self.build_log=build_log; self.deps_log=deps_log; self.manifest_parser=manifest_parser
        self.loaded_dyndep_files=set()
        self.visiting=[]
    def _recipient_edges(self,dynnode):
        return [e for e in self.state.edges if e.dyndep_node is dynnode]
    def load_dyndeps_for_edge(self,edge):
        # returns True if loaded / not dyndep, False if pending (dyndep generated but not ready)
        # raises NinjaError for load errors
        if edge.dyndep_node is None or edge.dyndep_loaded:
            edge.dyndep_pending=False; return True
        dynnode=edge.dyndep_node
        dynnode.stat_if_necessary()
        if dynnode.mtime==0:
            if dynnode.in_edge is not None:
                edge.dyndep_pending=True; return False
            # will raise loading error
        else:
            # if dyndep file's generating edge is dirty, pending
            if dynnode.in_edge is not None:
                # ensure its dirty computed if status known and dirty
                if dynnode.status_known and dynnode.dirty:
                    edge.dyndep_pending=True; return False
                if not dynnode.status_known:
                    # Visit dynnode to determine dirty (but avoid recursion loops: caller usually visits inputs first)
                    pass
        if dynnode.path in self.loaded_dyndep_files:
            edge.dyndep_loaded=True; edge.dyndep_pending=False; return True
        recipients=self._recipient_edges(dynnode)
        stmts=load_dyndep_file(self.state,dynnode.path,recipients,self.manifest_parser)
        self.loaded_dyndep_files.add(dynnode.path)
        apply_dyndep_statements(self.state,stmts,recipients)
        return True
    def load_deps_for_edge(self,edge,trigger_node):
        # sets edge.dep_nodes and returns (deps_dirty bool)
        if edge.deps_loaded:
            return edge.deps_dirty_reason
        edge.deps_loaded=True; edge.dep_nodes=[]
        if edge.is_phony():
            return False
        deps_type=edge.get_unescaped_binding("deps")
        depfile=edge.get_unescaped_binding("depfile")
        deps_dirty=False
        if deps_type!="":
            if deps_type not in ("gcc","msvc"):
                Fatal(f"unknown deps type '{deps_type}'")
            # deps log
            if self.deps_log is None:
                EXPLAIN("deps for '%s' are missing", trigger_node.path)
                return True
            entry=self.deps_log.get_deps(trigger_node)
            # if trigger has no entry, try other outputs for a valid one? Use trigger semantics primarily
            if entry is None:
                # try any output entry (for multi-output visited via different node)
                found=None
                for o in edge.outputs:
                    e2=self.deps_log.get_deps(o)
                    if e2 is not None: found=e2; trigger_node=o; entry=e2; break
                if entry is None:
                    EXPLAIN("deps for '%s' are missing", trigger_node.path)
                    edge.deps_dirty_reason=True
                    return True
            trigger_node.stat_if_necessary()
            if entry.mtime!=trigger_node.mtime:
                EXPLAIN("stored deps info out of date for '%s' (%s vs %s)", trigger_node.path, entry.mtime, trigger_node.mtime)
                edge.deps_dirty_reason=True
                return True
            # valid
            for depnode in entry.deps:
                edge.dep_nodes.append(depnode)
                depnode.dep_loader_phantom=True
            return False
        elif depfile!="":
            with MetricTimer(g_metrics,"depfile load"):
                status,content,err=Disk.read_file(depfile)
                if status=="notfound":
                    EXPLAIN("depfile '%s' is missing", depfile)
                    edge.deps_dirty_reason=True
                    return True
                if status!="ok":
                    raise NinjaError(f"loading '{depfile}': {err}")
                try:
                    outs,ins=parse_depfile(content)
                except NinjaError as e:
                    raise NinjaError(f"{depfile}: {e.msg}")
                for p in ins:
                    node=self.state.get_node(canonicalize_path(p))
                    edge.dep_nodes.append(node)
                    node.dep_loader_phantom=True
                return False
        return False
    def recompute_dirty(self,node,validation_nodes=None):
        self._visit(node, validation_nodes)
    def _visit(self,node,validation_nodes=None):
        if node.status_known:
            return
        if node in self.visiting:
            idx=self.visiting.index(node)
            cycle=[n.path for n in self.visiting[idx:]]+[node.path]
            raise NinjaError("dependency cycle: " + " -> ".join(cycle))
        node.stat_if_necessary()
        edge=node.in_edge
        if edge is None:
            node.dirty=False; node.status_known=True; return
        if validation_nodes is not None:
            for v in edge.validations:
                if v not in validation_nodes:
                    validation_nodes.append(v)
        if edge.scan_evaluated:
            # output dirty already derived
            return
        self.visiting.append(node)
        try:
            # dyndep: first visit dyndep node if it is an input to determine pending.
            # We visit static inputs first (below) but need dyndep load before evaluating new inputs.
            # Approach: if dyndep node exists, visit it now.
            dyndep_pending=False
            if edge.dyndep_node is not None and not edge.dyndep_loaded:
                dn=edge.dyndep_node
                if dn is not node and dn not in self.visiting:
                    # visit dyndep node (its edge may be ...), ignore validation collection duplication handled
                    self._visit(dn, validation_nodes)
                # now try load
                try:
                    loaded=self.load_dyndeps_for_edge(edge)
                except NinjaError:
                    raise
                if not loaded:
                    dyndep_pending=True
            # Visit static inputs (including possibly new dyndep inputs)
            for inp in list(edge.inputs):
                self._visit(inp, validation_nodes)
            # depfile/deps loading (may explain missing)
            deps_dirty=False
            if not dyndep_pending:
                deps_dirty=self.load_deps_for_edge(edge,node)
                # visit dep nodes
                for depnode in list(edge.dep_nodes):
                    self._visit(depnode, None)
            else:
                deps_dirty=False
            # Determine dirty
            # Most recent non-order input
            most_recent=None; most_recent_mtime=0
            def consider(inp):
                nonlocal most_recent,most_recent_mtime
                mt=inp.stat_if_necessary()
                if mt>most_recent_mtime:
                    most_recent_mtime=mt; most_recent=inp
            non_order_inputs=[]
            oo=set(id(x) for x in edge.order_only_inputs())
            # inputs order explicit/implicit then dep nodes; order-only excluded
            for inp in edge.inputs:
                if id(inp) in oo and inp in edge.order_only_inputs():
                    continue
                non_order_inputs.append(inp)
            # Above check by identity via slice positions is safer:
            non_order_inputs=edge.inputs[:len(edge.inputs)-edge.order_only_in] if edge.order_only_in else list(edge.inputs)
            for inp in non_order_inputs: consider(inp)
            for inp in edge.dep_nodes: consider(inp)
            any_input_dirty=False
            for inp in non_order_inputs:
                if inp.dirty:
                    EXPLAIN("%s is dirty", inp.path); any_input_dirty=True
            for inp in edge.dep_nodes:
                if inp.dirty:
                    # reference prints "<dep> is dirty" in some cases (hdr removed)
                    EXPLAIN("%s is dirty", inp.path); any_input_dirty=True
            if dyndep_pending:
                # Output cannot be determined clean yet; mark all outputs dirty (conservatively for plan pending)
                for out in edge.outputs:
                    out.dirty=True; out.status_known=True
                edge.scan_evaluated=False  # allow re-evaluation after dyndep loads; but status_known would block.
                # To allow re-evaluation, clear status_known for outputs? Builder will reset before re-scan.
                # Keep status known for this scan to make plan include as pending.
                return
            # command hash computed once if needed (non-phony and build log present)
            command_hash=None
            if not edge.is_phony() and self.build_log is not None:
                # Only compute if any output exists (to avoid fatal cycles on missing? reference computes for missing too in some paths?)
                # We compute lazily per output check below.
                pass
            for out in edge.outputs:
                out.dirty=self._recompute_output_dirty(edge,out,most_recent,most_recent_mtime,deps_dirty,any_input_dirty)
