            EXPLAIN("output %s older than most recent input %s (%s vs %s)", out.path, most_recent.path, out.mtime, most_recent_mtime)
            return True
        if self.build_log is not None:
            entry=self.build_log.lookup(out.path)
            is_generator=edge.get_binding_bool("generator")
            if entry is None:
                if not is_generator:
                    EXPLAIN("command line not found in log for %s", out.path)
