# ---------- dyndep ----------
class DyndepStatement:
    def __init__(self,out_node,imp_outs,imp_ins,restat):
        self.out=out_node; self.imp_outs=imp_outs; self.imp_ins=imp_ins; self.restat=restat

class DyndepParser:
    def __init__(self,state,filename,content,manifest_parser):
        self.state=state; self.lexer=Lexer(filename,content,manifest_parser); self.filename=filename
        self.parser=manifest_parser
    def parse(self, recipient_edges):
        # returns list of DyndepStatement; raises ParseError or NinjaError(msg)
        lexer=self.lexer
        # version line: skip newlines/comments? Lexer ReadToken skips comments.
        # Need parse an assignment manually.
        # Use tokens: expect ident
        # Blank file: first token EOF -> expected version blank
        # We need special handling to mirror messages.
        while True:
            t=lexer.read_token()
            if t.typ=="NEWLINE": continue
            break
        if t.typ!="IDENT":
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=t.start, line=t.line, show=False)
        if t.value=="build" or t.value in ("rule","pool","default","include","subninja"):
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=t.start, line=t.line, show=False)
        name=t.value
        eq=lexer.read_token()
        if eq.typ!="EQUALS":
            got=TOKEN_DESCR.get(eq.typ,eq.typ)
            lexer.error(f"expected '=', got {got}", pos=eq.start, line=eq.line)
        lexer.eat_whitespace()
        dummy_env=BindingEnv()
        ev,line,nlpos=lexer.read_eval_string("value", equals_pos=eq.start)
        val=ev.evaluate(dummy_env)
        if name!="ninja_dyndep_version":
            lexer.error("expected 'ninja_dyndep_version = ...'", pos=nlpos, line=line)
        # parse version numeric major/minor from val
        major=0; minor=0
        m=re.match(r"\s*(\d+)",val)
        if m:
            major=int(m.group(1)); rest=val[m.end():]
            if rest.startswith("."):
                m2=re.match(r"(\d+)",rest[1:])
                if m2: minor=int(m2.group(1))
        if not (major==1 and minor==0):
            lexer.error(f"unsupported 'ninja_dyndep_version = {val}'", pos=nlpos, line=line)
        # map output path -> edge (any output of recipient edges)
        out_to_edge={}
        for e in recipient_edges:
            for o in e.outputs:
                out_to_edge[o.path]=e
        statements=[]; seen_out_paths=set()
        seen_edges=set()
        while True:
            t=lexer.read_token()
            if t.typ=="EOF": break
            if t.typ=="NEWLINE": continue
            if t.typ=="IDENT":
                if t.value=="build":
                    stmt=self.parse_build_statement(out_to_edge, seen_out_paths)
                    statements.append(stmt)
                    continue
                elif t.value in ("rule","pool","default","include","subninja"):
                    lexer.error(f"unexpected '{t.value}'", pos=t.start, line=t.line, show=False)
                else:
                    lexer.error("unexpected identifier", pos=t.start, line=t.line, show=False)
            elif t.typ=="INDENT":
                lexer.error("unexpected indent", pos=t.start, line=t.line, show=False)
            elif t.typ=="ERROR":
                lexer.error(t.value, pos=t.start, line=t.line, show=False)
            else:
                val=t.value if t.value else t.typ
                lexer.error(f"unexpected '{val}'", pos=t.start, line=t.line, show=False)
        # check all recipient edges mentioned: For each edge, at least one statement for one of its outputs?
        # Reference expects a statement for each build statement (edge). Use first output in error if missing.
        mentioned_edges=set()
        for s in statements:
            e=out_to_edge.get(s.out.path)
            if e is not None: mentioned_edges.add(id(e))
