        outputs=[]; imp_outs=[]
        while True:
            ev=lexer.read_path()
            if ev.empty(): break
            val=ev.evaluate(BindingEnv())
            if val=="":
                raise ParseError(f"{self.filename}:{lexer.line_number}: empty path\n\n")
            outputs.append(canonicalize_path(val))
        # implicit outs
        if lexer.ofs<lexer.len and lexer.content[lexer.ofs]=="|":
            nxt=lexer.content[lexer.ofs+1] if lexer.ofs+1<lexer.len else ""
            if nxt not in "|@":
