                    edge.dep_nodes.append(node)
                    node.dep_loader_phantom=True
                return False
        return False
    def recompute_dirty(self,node,validation_nodes=None):
        self._visit(node, validation_nodes)
    def _visit(self,node,validation_nodes=None):
        if node.status_known:
            return
        if node in self.visiting:
            idx=self.visiting.index(node)
            cycle=[n.path for n in self.visiting[idx:]]+[node.path]
            raise NinjaError("dependency cycle: " + " -> ".join(cycle))
        node.stat_if_necessary()
