            # output dirty already derived
            return
        self.visiting.append(node)
        try:
            # dyndep: first visit dyndep node if it is an input to determine pending.
            # We visit static inputs first (below) but need dyndep load before evaluating new inputs.
            # Approach: if dyndep node exists, visit it now.
            dyndep_pending=False
            if edge.dyndep_node is not None and not edge.dyndep_loaded:
                dn=edge.dyndep_node
                if dn is not node and dn not in self.visiting:
                    # visit dyndep node (its edge may be ...), ignore validation collection duplication handled
                    self._visit(dn, validation_nodes)
