# ---------- build status ----------
def get_terminal_width():
    try:
        import shutil
        w=shutil.get_terminal_size(fallback=(0,24)).columns
        return w
    except Exception:
        return 0
def elide_middle(s,width):
    if width<=0: return s
    if len(s)<=width: return s
    if width<3: return s[:width]
    front=(width-3)//2
    back=width-3-front
    return s[:front]+"..."+(s[len(s)-back:] if back>0 else "")

class BuildStatus:
    def __init__(self,config):
        self.config=config
        self.total=0
        self.started=0; self.finished=0; self.running=0
        self.start_time_ms=None
        self.finish_times=[]  # ms elapsed of finishes
        self.smart = False
        self.format_str=os.environ.get("NINJA_STATUS", "[%f/%t] ")
        self._validate_format()
        self.console_running=False
        self.buffered=[]
    def _validate_format(self):
        # validate eagerly like reference: unknown placeholders fatal - but only when status created for a build
        i=0; s=self.format_str
        valid=set("stprufoc eEwWP%".replace(" ",""))
        while i<len(s):
            if s[i]=="%":
                if i+1>=len(s):
                    Fatal("unknown placeholder '%\x00' in $NINJA_STATUS")
                c=s[i+1]
                if c not in valid:
                    Fatal(f"unknown placeholder '%{c}' in $NINJA_STATUS")
                i+=2
            else: i+=1
    def reset_for_builder(self):
        self.started=0; self.finished=0; self.running=0; self.finish_times=[]
        self.start_time_ms=time.perf_counter()*1000.0
        # total intentionally not reset
        self.smart = (self.config.verbosity==0 and sys.stdout.isatty())
        self.console_running=False; self.buffered=[]
    def elapsed_ms(self):
        if self.start_time_ms is None: return 0.0
        return time.perf_counter()*1000.0-self.start_time_ms
    def format_status(self,edge):
        # called with counters in their current state
        out=[]
        s=self.format_str; i=0
        elapsed=self.elapsed_ms()/1000.0
        total=self.total
        finished=self.finished
        def fmt_time_hms(sec):
            sec=int(sec)
            h=sec//3600; m=(sec%3600)//60; ss=sec%60
            if h>0: return f"{h}:{m:02d}:{ss:02d}"
            return f"{m:02d}:{ss:02d}"
        # ETA
        if finished>0 and total>0:
            predicted=elapsed*total/finished
            remaining=max(0.0,predicted-elapsed)
            pct_time=int((elapsed/predicted*100) if predicted>0 else 100)
        else:
            remaining=0.0; pct_time=0
        while i<len(s):
            if s[i]!="%": out.append(s[i]); i+=1; continue
            c=s[i+1]; i+=2
            if c=="%": out.append("%")
            elif c=="s": out.append(str(self.started))
            elif c=="t": out.append(str(total))
            elif c=="f": out.append(str(finished))
            elif c=="r": out.append(str(self.running))
            elif c=="u": out.append(str(max(0,total-self.started)))
            elif c=="p": out.append(f"{int(finished*100/total) if total else 100:3d}%")
            elif c=="P": out.append(f"{pct_time:3d}%")
            elif c=="e": out.append(f"{elapsed:.3f}")
            elif c=="E": out.append(f"{remaining:.3f}")
            elif c=="w": out.append(fmt_time_hms(elapsed))
            elif c=="W": out.append(fmt_time_hms(remaining))
            elif c=="o":
                out.append(f"{(finished/elapsed if elapsed>0 else 0):.1f}")
            elif c=="c":
                out.append(self.current_rate())
            else: out.append("")
        return "".join(out)
    def current_rate(self):
        # approximate: need parallelism+? Use window = parallelism from config if explicit else guess?
        # Reference: available after enough finishes. Implement a window of config.parallelism (capped)
        window=self.config.parallelism
        if window is None or window>1000000: window=guess_parallelism()
        if window<=1: return "?"
        if len(self.finish_times) < 2:
            return "?"
        # times are elapsed ms at finishes (including current before append? caller appends before format for finished)
        # Use last `window` intervals
        times=self.finish_times
        if len(times) <= window:
            # For j=2, reference shows ? for first 2 then value at 3rd. Require > window
            if len(times) <= window: return "?" if len(times)<=window and False else self._rate_from(times,window)
        return self._rate_from(times,window)
    def _rate_from(self,times,window):
        # mimic observed variability roughly: window / (now - time of finish window ago)
        if len(times)<2: return "?"
        idx=max(0,len(times)-1-window)
        span_ms=times[-1]-times[idx]
        if span_ms<=0: span_ms=1
        # If not enough history for j=3 second finish gave a value in reference; our simple gives value. Accept differences.
        return f"{window/(span_ms/1000.0):.1f}"
    def _desc(self,edge):
        if self.config.verbosity==1: # verbose
            return edge.get_command()
        desc=edge.get_description()
        if desc!="": return desc
        return edge.get_command()
    def _emit(self,data):
        out_write(data)
    def _emit_event(self, chunks, is_console_finished=False):
        # chunks: list of strings to output in order for a finished edge
        if self.console_running and not is_console_finished:
            self.buffered.append(chunks); return
        for ch in chunks: self._emit(ch)
        if is_console_finished:
            # flush buffered
            buf=self.buffered; self.buffered=[]
            for ev in buf:
                for ch in ev: self._emit(ch)
    def edge_started(self,edge):
        self.started+=1; self.running+=1
        is_console = (edge.pool is not None and getattr(edge.pool,'is_console',False))
        if self.config.verbosity==2: # quiet
            if is_console: self.console_running=True
            return
        text=self.format_status(edge)+self._desc(edge)
        if is_console:
            self.console_running=True
            if self.smart:
                line=elide_middle(text,get_terminal_width())
                self._emit_event(["\r"+line+"\x1b[K\n"], is_console_finished=False)
            else:
                # console start line is printed immediately, not buffered (it sets console mode)
                self._emit(text+"\n")
        elif self.smart:
            line=elide_middle(text,get_terminal_width())
            # if a console is running, smart lines are buffered by printer? In reference other edges' started prints are suppressed while console.
            if self.console_running:
                pass
            else:
                self._emit("\r"+line+"\x1b[K")
    def edge_finished(self,edge,success,output,exit_code):
        self.finished+=1
        self.finish_times.append(self.elapsed_ms())
        is_console = (edge.pool is not None and getattr(edge.pool,'is_console',False))
        # Build chunks
        chunks=[]
        already_printed_start=is_console and self.config.verbosity!=2
        if self.config.verbosity!=2 and not already_printed_start:
            text=self.format_status(edge)+self._desc(edge)
            if self.smart:
                line=elide_middle(text,get_terminal_width())
                chunks.append("\r"+line+"\x1b[K\n")
            else:
                chunks.append(text+"\n")
        if success:
            if output and not is_console:
                chunks.append(output if output.endswith("\n") or isinstance(output,bytes) and output.endswith(b"\n") else output+"\n")
        else:
            # FAILED block
            outs="".join(o.path+" " for o in edge.outputs)
            if self.smart:
                chunks.append(f"\x1b[31mFAILED: [code={exit_code}] \x1b[0m{outs}\n")
            else:
                chunks.append(f"FAILED: [code={exit_code}] {outs}\n")
            chunks.append(edge.get_command()+"\n")
            if output and not is_console:
                chunks.append(output if (isinstance(output,str) and output.endswith("\n")) else output+"\n")
        # running decrement after formatting (%r included this edge)
        self.running-=1
        if is_console:
            self.console_running=False
            self._emit_event(chunks, is_console_finished=True)
        else:
            self._emit_event(chunks, is_console_finished=False)
    def build_stopped(self,reason):
        line=f"ninja: build stopped: {reason}.\n"
        if self.console_running:
            self.buffered.append([line])
        else:
            self._emit(line)
    def no_work(self):
        if self.config.verbosity!=2:
            self._emit("ninja: no work to do.\n")

class BuildConfig:
    def __init__(self):
        self.verbosity=0 #0 normal,1 verbose,2 quiet
        self.dry_run=False
        self.parallelism=guess_parallelism()
        self.parallelism_explicit=False
        self.failures_allowed=1
        self.max_load=0.0
        self.input_file="build.ninja"
        self.working_dir=None

# ---------- Plan / Builder ----------
class RunningJob:
    pass

class Builder:
    def __init__(self,state,config,build_log,deps_log,manifest_parser,status,disk=None):
        self.state=state; self.config=config; self.build_log=build_log; self.deps_log=deps_log
        self.manifest_parser=manifest_parser; self.status=status
        self.scan=DependencyScan(state,build_log,deps_log,manifest_parser)
        self.wanted=set()  # edges to start
        self.pending=set() # dyndep want-to-finish edges
        self.finished_edges=set()
        self.failed_edges=set()
        self.ready=[] # heap entries
        self.edge_state={} # edge-> 'wanted','pending','ready','running','done','clean','failed'
        self.node_ready={}
        self.running_jobs=[]
        self.failures=0
        self.last_failure_code=1
        self.interrupted=False
        self.interrupt_code=130
        self.build_start_perf=time.perf_counter()
        self.status.reset_for_builder()
        self._total_added=False
        self._old_handlers={}
        self._install_signals()
        self.pool_counts={}
        # jobserver
        self.jobserver=None
        self.jobserver_mode_printed=False
        self._init_jobserver()
    # signals
    def _sig_handler(self,signum,frame):
        self.interrupted=True
    def _install_signals(self):
        try:
            for sig in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
                self._old_handlers[sig]=signal.getsignal(sig)
                signal.signal(sig, self._sig_handler)
        except Exception:
            pass
    def _restore_signals(self):
        try:
            for sig, h in self._old_handlers.items():
                signal.signal(sig,h)
        except Exception: pass
        self._cleanup_lock_file()
    def _cleanup_lock_file(self):
        # Remove .ninja_lock in builddir like reference builder cleanup (ignore errors) - only for real builders after targets collected
        try:
            bd=self.state.bindings.lookup_variable("builddir") if self.state else ""
            p=join_build_dir(bd,".ninja_lock")
            Disk.remove_file(p)
        except Exception:
            pass
    # jobserver init
    def _init_jobserver(self):
        if self.config.dry_run or self.config.parallelism_explicit:
            return
        makeflags=os.environ.get("MAKEFLAGS")
        if makeflags is None: return
        auth=None
        for word in makeflags.split():
            if word.startswith("--jobserver-auth="): auth=word[len("--jobserver-auth="):]
            elif word.startswith("--jobserver-fds="): auth=word[len("--jobserver-fds="):]
        if auth is None: return
        if auth.startswith("fifo:"):
            # Print mode detected with full MAKEFLAGS
            print_out(f"ninja: Jobserver mode detected: {makeflags}")
            fifopath=auth[len("fifo:"):]
            if fifopath=="":
                Error("Could not initialize jobserver: Empty fifo path"); return
            try:
                st=os.stat(fifopath)
            except OSError as e:
                Error(f"Could not initialize jobserver: Error opening fifo for reading: {e.strerror or str(e)}"); return
            if not stat.S_ISFIFO(st.st_mode):
                Error(f"Could not initialize jobserver: Not a fifo path: {fifopath}"); return
            try:
                rfd=os.open(fifopath, os.O_RDWR|os.O_NONBLOCK)
                wfd=os.open(fifopath, os.O_WRONLY|os.O_NONBLOCK)
            except OSError as e:
                Error(f"Could not initialize jobserver: Error opening fifo for reading: {e.strerror or str(e)}"); return
            self.jobserver={"rfd":rfd,"wfd":wfd,"tokens":[]} # tokens list of bytes acquired 'in hand' beyond implicit? We track per job
            self.jobserver_acquired=[] # stack of token bytes held for running extra jobs
        elif "," in auth:
            Warning(f"Ignoring jobserver: Pipe-based protocol is not supported! [{makeflags}]")
        else:
            Warning(f"Ignoring jobserver: Semaphore mode is not supported on Posix! [{makeflags}]")
    def _jobserver_acquire(self):
        # return token byte or None if none available, or '' for implicit handled by caller
        if not self.jobserver: return None
        try:
            data=os.read(self.jobserver["rfd"],1)
            if data: return data
            return None
        except BlockingIOError:
            return None
        except OSError:
            return None
    def _jobserver_release(self,token):
        if not self.jobserver or not token: return
        try: os.write(self.jobserver["wfd"],token)
        except OSError: pass
    def _close_jobserver(self):
        if self.jobserver:
            for k in ("rfd","wfd"):
                try: os.close(self.jobserver[k])
                except Exception: pass
            self.jobserver=None
    # target adding
    def add_target(self,node, parent_node=None, top_level=False):
        # returns None or raises NinjaError missing/cycle etc via scan done by caller
        edge=node.in_edge
        if edge is None:
            return
        self._add_edge(edge, via_node=node)
    def _is_node_ready_initial(self,node):
        if node.in_edge is None: return True
        if id(node.in_edge) in [id(e) for e in self.wanted]: return False
        if node.in_edge in self.wanted or node.in_edge in self.pending: return False
        return True
    def _add_edge(self,edge, via_node):
        if edge in self.edge_state:
            return
        # determine wanted vs clean/pending
        any_dirty=False
        for o in edge.outputs:
            if o.dirty: any_dirty=True
        is_pending = edge.dyndep_node is not None and not edge.dyndep_loaded
        if not any_dirty and not is_pending:
            self.edge_state[edge]="clean"
            for o in edge.outputs: self.node_ready[id(o)]=True
            return
        # check missing inputs first (in order) and recurse
        # First gather prerequisites (static + dep_nodes)
        prereqs=list(edge.inputs)+list(edge.dep_nodes)
        for inp in prereqs:
            if inp.in_edge is None and not inp.dep_loader_phantom:
                inp.stat_if_necessary()
                if inp.mtime==0:
                    raise NinjaError(f"'{inp.path}', needed by '{via_node.path}', missing and no known rule to make it")
        if is_pending and not any_dirty:
            self.edge_state[edge]="pending"; self.pending.add(edge)
        else:
            self.edge_state[edge]="wanted"; self.wanted.add(edge)
        for inp in prereqs:
            if inp.in_edge is not None:
                self._add_edge(inp.in_edge, via_node=inp)
    def compute_priorities(self):
        with MetricTimer(g_metrics,"ComputeCriticalPath"):
            # priority = longest downstream chain of wanted/pending edges
            memo={}
            visiting=set()
            def prio(edge):
                if id(edge) in memo: return memo[id(edge)]
                if id(edge) in visiting: return 0
                visiting.add(id(edge))
                best=0
                for o in edge.outputs:
                    for oe in o.out_edges:
                        if oe in self.wanted or oe in self.pending:
                            best=max(best,prio(oe))
                visiting.discard(id(edge))
                val=best+1; memo[id(edge)]=val; return val
            for e in list(self.wanted)+list(self.pending):
                e.priority=prio(e)
    def prepare(self):
        # count command edges (non-phony wanted)
        count=0
        for e in self.wanted:
            if not e.is_phony(): count+=1
        if not self._total_added:
            self.status.total+=count; self._total_added=True
            self._initial_command_count=count
        self.compute_priorities()
        # initialize ready determination
    def _edge_prereqs(self,edge):
        return list(edge.inputs)+list(edge.dep_nodes)
    def _prereqs_ready(self,edge):
        for inp in self._edge_prereqs(edge):
            ee=inp.in_edge
            if ee is None: continue
            st=self.edge_state.get(ee)
            if st in ("wanted","pending","ready","running"):
                return False
            if st in ("failed",):
                return False
            # clean/done
        return True
    def _all_wanted_done(self):
        for e in list(self.wanted):
            if self.edge_state.get(e) not in ("done","clean","failed"): return False
        for e in list(self.pending):
            if self.edge_state.get(e) not in ("done","clean","failed"): return False
        return True
    # process spawning
    def _capture_record_time(self):
        bd=self.state.bindings.lookup_variable("builddir")
        path=join_build_dir(bd,".ninja_lock")
        ok,stage,err=Disk.write_file(path,"")
        if not ok:
            what="Unable to create file" if stage=="create" else "Unable to close the file"
            Error(f"WriteFile({path}): {what}. {err}")
            return time.time_ns()
        mt=Disk.stat(path)
        return mt if mt!=0 else time.time_ns()
    def _start_edge(self,edge):
        with MetricTimer(g_metrics,"StartEdge"):
            return self._start_edge_inner(edge)
    def _start_edge_inner(self,edge):
        # returns RunningJob or raises NinjaError with empty msg for build stopped '.'
        # create output dirs
        for out in edge.outputs:
            ok,err=Disk.make_dir_for_file(out.path)
            if not ok:
                raise NinjaError("")  # empty err -> build stopped: .
        depfile=edge.get_unescaped_binding("depfile")
        if depfile:
            ok,err=Disk.make_dir_for_file(depfile)
            if not ok:
                raise NinjaError("")
        rspfile=edge.get_unescaped_binding("rspfile")
        if rspfile:
            content=edge.get_binding("rspfile_content",True)
            ok,stage,err=Disk.write_file(rspfile,content)
            if not ok:
                what="Unable to create file" if stage=="create" else "Unable to close the file"
                Error(f"WriteFile({rspfile}): {what}. {err}")
                raise NinjaError("")
        command=edge.get_command()
        record_mtime=0
        if not self.config.dry_run:
            record_mtime=self._capture_record_time()
        edge.record_mtime=record_mtime
        # capture pre mtines for restat
        pre_mtimes=[]
        for o in edge.outputs:
            o.reset_stat(); pre_mtimes.append(o.stat_if_necessary())
        is_console = edge.pool is not None and getattr(edge.pool,'is_console',False)
        self.status.edge_started(edge)
        start_ms=int((time.perf_counter()-self.build_start_perf)*1000)
        edge.command_start_ms=start_ms
        job=RunningJob(); job.edge=edge; job.command=command; job.start_ms=start_ms; job.pre_mtimes=pre_mtimes; job.rspfile=rspfile; job.is_console=is_console; job.token=getattr(edge,'_job_token',None)
        if self.config.dry_run:
            job.process=None; job.dry=True; job.done=True; job.output=b""; job.exit_code=0; job.signaled=None; job.end_ms=start_ms
            job.thread=None
        else:
            job.dry=False; job.done=False
            import subprocess
            try:
                if is_console:
                    p=subprocess.Popen(["/bin/sh","-c",command], stdin=None, stdout=None, stderr=None, preexec_fn=os.setpgrp)
                else:
                    p=subprocess.Popen(["/bin/sh","-c",command], stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, preexec_fn=os.setpgrp)
            except Exception as e:
                job.process=None; job.done=True; job.output=encode_bytes(str(e)); job.exit_code=1; job.signaled=None; job.end_ms=int((time.perf_counter()-self.build_start_perf)*1000)
                self.running_jobs.append(job); return job
            job.process=p
            # reader thread for piped output
            job.output=b""; job.exit_code=0; job.signaled=None; job.raw_status=0
            def reader():
                out=b""
                if not is_console:
                    try:
                        out=p.stdout.read() if p.stdout else b""
                    except Exception: out=b""
                # Use waitpid via p.wait (python loses core flag; we will compute below using a second wait? Popen stores returncode)
                rc=p.wait()
                job.output=out or b""
                job.end_ms=int((time.perf_counter()-self.build_start_perf)*1000)
                if rc is not None and rc<0:
                    job.signaled=-rc
                    # core flag unknown; approximate signals that dump core
                    core_sigs={signal.SIGABRT, signal.SIGBUS, signal.SIGFPE, signal.SIGILL, signal.SIGQUIT, signal.SIGSEGV, signal.SIGSYS, signal.SIGTRAP, signal.SIGXCPU, signal.SIGXFSZ}
                    if job.signaled in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
                        job.exit_code=130; job.interrupted_sig=True
                    elif job.signaled in core_sigs:
                        job.exit_code=256+job.signaled
                    else:
                        job.exit_code=128+job.signaled
                else:
                    job.exit_code=rc if rc is not None else 0
                    job.interrupted_sig=False
                job.done=True
            job.thread=threading.Thread(target=reader,daemon=True); job.thread.start()
        # pool count
        if edge.pool: edge.pool.current+=1
        self.running_jobs.append(job)
        self.edge_state[edge]="running"
        return job
    def _finish_job(self,job):
        with MetricTimer(g_metrics,"FinishCommand"):
            return self._finish_job_inner(job)
    def _finish_job_inner(self,job):
        edge=job.edge
        success=(job.exit_code==0 and not getattr(job,'interrupted_sig',False))
        output_bytes=job.output if isinstance(job.output,bytes) else encode_bytes(job.output or b"")
        output=output_bytes.decode('utf-8','surrogateescape')
        exit_code=job.exit_code
        # deps extraction
        deps_type=edge.get_unescaped_binding("deps")
        extracted_deps=None
        if deps_type=="gcc":
            depfile=edge.get_unescaped_binding("depfile")
            if depfile:
                status,content,err=Disk.read_file(depfile)
                if status=="ok":
                    try:
                        outs,ins=parse_depfile(content)
                        extracted_deps=[self.state.get_node(canonicalize_path(p)) for p in ins]
                        if not g_keepdepfile:
                            Disk.remove_file(depfile)
                    except NinjaError as e:
                        # append to output, mark failure code 1
                        if output and not output.endswith("\n"): output+="\n"
                        output+=e.msg+"\n"; success=False; exit_code=1
                elif status=="notfound":
                    extracted_deps=[]
                else:
                    if output and not output.endswith("\n"): output+="\n"
                    output+=f"loading '{depfile}': {err}\n"; success=False; exit_code=1
            else:
                extracted_deps=[]
        elif deps_type=="msvc":
            prefix=edge.get_binding("msvc_deps_prefix")
            if prefix=="": prefix="Note: including file:"
            deps=[]; new_lines=[]
            for line in output.splitlines(True):
                stripped=line.rstrip("\r\n")
                if stripped.startswith(prefix):
                    rest=stripped[len(prefix):].strip()
                    if rest:
                        deps.append(self.state.get_node(canonicalize_path(rest)))
                else:
                    new_lines.append(line)
            output="".join(new_lines)
            extracted_deps=deps
        # status finished print
        self.status.edge_finished(edge,success,output,exit_code)
        # decrement pool
        if edge.pool and edge.pool.current>0: edge.pool.current-=1
        # rsp delete
        if job.rspfile and success and not g_keeprsp and not self.config.dry_run:
            Disk.remove_file(job.rspfile)
        # restat outputs and record
        if not self.config.dry_run:
            for o in edge.outputs:
                o.reset_stat(); o.stat_if_necessary()
        if success and not self.config.dry_run:
            # deps record
            if extracted_deps is not None and self.deps_log is not None:
                for o in edge.outputs:
                    ok,err=self.deps_log.record_deps(o,o.mtime,extracted_deps)
                    if not ok:
                        raise NinjaError(err)
            # build log record
            if self.build_log is not None:
                h=edge.evaluate_command_hash()
                ok,err=self.build_log.record_command(edge,job.start_ms,job.end_ms,edge.record_mtime,h)
                if not ok:
                    raise NinjaError(err)
        # plan state
        self.running_jobs.remove(job)
        if job.token:
            self._jobserver_release(job.token)
        if getattr(job,'interrupted_sig',False):
            self.edge_state[edge]="failed"; self.interrupted=True; return
        if success:
            self.edge_state[edge]="done"; self.finished_edges.add(edge)
            # restat clean propagation
            is_restat=edge.get_binding_bool("restat") or edge.restat_dyndep
            if is_restat and not self.config.dry_run:
                for o,pre in zip(edge.outputs,job.pre_mtimes):
                    if pre!=0 and o.mtime==pre:
                        self._clean_node(o)
            # dyndep activation for outputs
            for o in list(edge.outputs):
                self._activate_dyndep_for_node(o)
        else:
            self.edge_state[edge]="failed"; self.failed_edges.add(edge); self.failures+=1; self.last_failure_code=exit_code if exit_code!=0 else 1
    def _clean_node(self,node):
        # mark node clean and try to cancel consumers that are now clean upon re-evaluation
        node.dirty=False
        for oe in list(node.out_edges):
            if self.edge_state.get(oe) not in ("wanted","pending","ready"): continue
            # if any non-order input still dirty (and not this node), keep
            non_order=oe.inputs[:len(oe.inputs)-oe.order_only_in] if oe.order_only_in else list(oe.inputs)
            if any(inp.dirty for inp in non_order): continue
            if any(inp.dirty for inp in oe.dep_nodes): continue
            # recompute output dirty for its outputs (without input-dirty)
            # most recent
            most_recent=None; most_mtime=0
            for inp in non_order+list(oe.dep_nodes):
                mt=inp.stat_if_necessary()
                if mt>most_mtime: most_mtime=mt; most_recent=inp
            all_clean=True
            for out in oe.outputs:
                # use scan logic but without explain for this probe: temporarily disable explain
                global g_explain
                old=g_explain; g_explain=False
                try:
                    d=self.scan._recompute_output_dirty(oe,out,most_recent,most_mtime,oe.deps_dirty_reason,False)
                finally:
                    g_explain=old
                if d: all_clean=False
            if all_clean:
                # cancel edge
                self.edge_state[oe]="clean"
                if oe in self.wanted:
                    self.wanted.discard(oe)
                    if not oe.is_phony(): self.status.total-=1
                if oe in self.pending: self.pending.discard(oe)
                for out in oe.outputs:
                    self._clean_node(out)
    def _activate_dyndep_for_node(self,node):
        recipients=self.scan._recipient_edges(node)
        for edge in recipients:
            if edge.dyndep_loaded: continue
            # load (may raise NinjaError)
            loaded=self.scan.load_dyndeps_for_edge(edge)
            if not loaded: continue
            # re-evaluate this edge's outputs
            for o in edge.outputs:
                o.status_known=False
            edge.scan_evaluated=False
            # Use scan visit on each output; inputs already visited will return, new inputs visited.
            for o in list(edge.outputs):
                self.scan._visit(o,None)
            # Now decide plan state
            was_pending = self.edge_state.get(edge)=="pending"
            was_wanted = self.edge_state.get(edge)=="wanted"
            any_dirty=any(o.dirty for o in edge.outputs)
            if any_dirty:
                if was_pending:
                    # transition to wanted and increase total
                    self.pending.discard(edge); self.wanted.add(edge); self.edge_state[edge]="wanted"
                    if not edge.is_phony(): self.status.total+=1
                    # add new prereq edges
                    for inp in list(edge.inputs)+list(edge.dep_nodes):
                        if inp.in_edge is not None and inp.in_edge not in self.edge_state:
                            self._add_edge(inp.in_edge, via_node=inp)
                elif was_wanted:
                    for inp in list(edge.inputs)+list(edge.dep_nodes):
                        if inp.in_edge is not None and inp.in_edge not in self.edge_state:
                            self._add_edge(inp.in_edge, via_node=inp)
                else:
                    # edge wasn't in plan (its output maybe input to wanted) - add if an output is needed?
                    # If any consumer is wanted/pending, add.
                    needed=False
                    for o in edge.outputs:
                        for oe in o.out_edges:
                            if self.edge_state.get(oe) in ("wanted","pending","ready","running"): needed=True
                    if needed:
                        self._add_edge(edge, via_node=edge.outputs[0])
                        if edge in self.wanted and not edge.is_phony():
                            # _add_edge may have added; total accounting in prepare only initial. Add here if newly wanted after prepare.
                            pass
            else:
                if was_pending or was_wanted:
                    # mark clean
                    if was_wanted and not edge.is_phony():
                        self.status.total-=1
                    self.wanted.discard(edge); self.pending.discard(edge); self.edge_state[edge]="clean"
    def build(self):
        # returns (exit_code, err_reason_or_None, already_ran_count)
        # Caller has added targets and called prepare()
        ran=0
        try:
            while True:
                if self.interrupted:
                    self._abort_running()
                    return (130,"interrupted by user",ran)
                # start ready edges
                made_progress=False
                # Build list of candidate edges sorted by priority/id
                candidates=[]
                for e in list(self.wanted)+list(self.pending):
                    if self.edge_state.get(e) in ("wanted","pending") and self._prereqs_ready(e):
                        candidates.append(e)
                candidates.sort(key=lambda e:(-e.priority,e.id))
                # phony handling and starting
                delayed=[]
                for edge in candidates:
                    if self.interrupted: break
                    if self.edge_state.get(edge) not in ("wanted","pending"): continue
                    if not self._prereqs_ready(edge): continue
                    # dyndep pending activation when prereqs ready
                    if edge.dyndep_node is not None and not edge.dyndep_loaded:
                        # Activate now (dyndep node should be ready)
                        self._activate_dyndep_for_node(edge.dyndep_node)
                        made_progress=True
                        continue
                    if edge.is_phony():
                        self.edge_state[edge]="done"; self.finished_edges.add(edge); self.wanted.discard(edge); self.pending.discard(edge)
                        made_progress=True; continue
                    if self.edge_state.get(edge)=="pending":
                        # pending but dyndep loaded should have transitioned; treat as clean
                        self.edge_state[edge]="clean"; self.pending.discard(edge); made_progress=True; continue
                    # failure limit
                    if self.failures>0 and self.config.failures_allowed!=0 and self.failures>=self.config.failures_allowed:
                        delayed.append(edge); continue
                    # parallelism / pools / load / jobserver
                    if not self._can_run_more(edge):
                        delayed.append(edge); continue
                    # acquire jobserver token if needed
                    token=None
                    if self.jobserver:
                        # implicit slot for first running job
                        if len(self.running_jobs)>0:
                            token=self._jobserver_acquire()
                            if token is None:
                                delayed.append(edge); continue
                    edge._job_token=token
                    try:
                        job=self._start_edge(edge)
                    except NinjaError as e:
                        if token: self._jobserver_release(token)
                        # empty msg means build stopped: .
                        return (1, e.msg if e.msg else "", ran)
                    self.wanted.discard(edge)  # running tracked separately; keep edge_state running
                    # wanted set is used for completion check via edge_state, so removing ok but _all check uses edge_state
                    ran+=1; made_progress=True
                    if self.config.dry_run:
                        # finish immediately
                        self._finish_job(job)
                if self._all_done():
                    break
                # wait for running
                if self.running_jobs:
                    # poll for a done job
                    finished=None
                    while finished is None:
                        if self.interrupted:
                            self._abort_running(); return (130,"interrupted by user",ran)
                        for j in list(self.running_jobs):
                            if j.done: finished=j; break
                        if finished is None:
                            time.sleep(0.002)
                    self._finish_job(finished)
                    if self.interrupted:
                        self._abort_running(); return (130,"interrupted by user",ran)
                    continue
                else:
                    # no running jobs
                    if made_progress:
                        continue
                    # delayed by load average?
                    if delayed and self.config.max_load>0:
                        # if no running, reference starts one regardless, handled in _can_run_more. So not here.
                        time.sleep(0.05); continue
                    # jobserver waiting for external tokens with no running shouldn't happen due implicit slot
                    break
            # determine result
            if self.interrupted:
                return (130,"interrupted by user",ran)
            if self.failures>0:
                # decide message
                if self.config.failures_allowed==0:
                    # infinite: if there are still wanted edges blocked, cannot make progress; if all attempted?
                    # Reference: -k0 with all independent failed gives cannot make progress.
                    # -k N where failures == N gives subcommand(s) failed; -k0 never equals.
                    return (self.last_failure_code,"cannot make progress due to previous errors",ran)
                # failures_allowed finite
                if self.failures>=self.config.failures_allowed:
                    msg="subcommand failed" if self.config.failures_allowed==1 else "subcommands failed"
                    # But if failures_allowed e.g. 3 and exactly 3 failures all done, reference gave subcommands failed
                    return (self.last_failure_code,msg,ran)
                else:
                    return (self.last_failure_code,"cannot make progress due to previous errors",ran)
            # if there remain wanted edges not done (blocked by failures handled above)
            return (0,None,ran)
        finally:
            self._close_jobserver()
            self._restore_signals()
    def _all_done(self):
        for e,st in list(self.edge_state.items()):
            if st in ("wanted","pending","ready","running"): return False
        return len(self.running_jobs)==0
    def _can_run_more(self,edge):
        # pool
        if edge.pool is not None and edge.pool.should_delay():
            return False
        # parallelism
        par=self.config.parallelism
        if par is not None and par>0 and len(self.running_jobs)>=par:
            return False
        # load average
        if self.config.max_load>0 and len(self.running_jobs)>0:
            try:
                load=os.getloadavg()[0]
                if load>self.config.max_load: return False
            except Exception: pass
        return True
    def _abort_running(self):
        for job in list(self.running_jobs):
            p=getattr(job,'process',None)
            if p is not None:
                try:
                    os.killpg(p.pid, signal.SIGKILL)
                except Exception:
                    try: p.kill()
                    except Exception: pass
            if getattr(job,'thread',None):
                job.thread.join(timeout=2)
            if edge:=job.edge:
                if edge.pool and edge.pool.current>0: edge.pool.current-=1
            if getattr(job,'token',None): self._jobserver_release(job.token)
        self.running_jobs=[]

PYEOF
"}

actions.command:
cat >> main.py << 'PYEOF'

# ---------- build status ----------
def get_terminal_width():
    try:
        import shutil
        w=shutil.get_terminal_size(fallback=(0,24)).columns
        return w
    except Exception:
        return 0
def elide_middle(s,width):
    if width<=0: return s
    if len(s)<=width: return s
    if width<3: return s[:width]
    front=(width-3)//2
    back=width-3-front
    return s[:front]+"..."+(s[len(s)-back:] if back>0 else "")

class BuildStatus:
    def __init__(self,config):
        self.config=config
        self.total=0
        self.started=0; self.finished=0; self.running=0
        self.start_time_ms=None
        self.finish_times=[]  # ms elapsed of finishes
        self.smart = False
        self.format_str=os.environ.get("NINJA_STATUS", "[%f/%t] ")
        self._validate_format()
        self.console_running=False
        self.buffered=[]
    def _validate_format(self):
        # validate eagerly like reference: unknown placeholders fatal - but only when status created for a build
        i=0; s=self.format_str
        valid=set("stprufoc eEwWP%".replace(" ",""))
        while i<len(s):
            if s[i]=="%":
                if i+1>=len(s):
                    Fatal("unknown placeholder '%\x00' in $NINJA_STATUS")
                c=s[i+1]
                if c not in valid:
                    Fatal(f"unknown placeholder '%{c}' in $NINJA_STATUS")
                i+=2
            else: i+=1
    def reset_for_builder(self):
        self.started=0; self.finished=0; self.running=0; self.finish_times=[]
        self.start_time_ms=time.perf_counter()*1000.0
        # total intentionally not reset
        self.smart = (self.config.verbosity==0 and sys.stdout.isatty())
        self.console_running=False; self.buffered=[]
    def elapsed_ms(self):
        if self.start_time_ms is None: return 0.0
        return time.perf_counter()*1000.0-self.start_time_ms
    def format_status(self,edge):
        # called with counters in their current state
        out=[]
        s=self.format_str; i=0
        elapsed=self.elapsed_ms()/1000.0
        total=self.total
        finished=self.finished
        def fmt_time_hms(sec):
            sec=int(sec)
            h=sec//3600; m=(sec%3600)//60; ss=sec%60
            if h>0: return f"{h}:{m:02d}:{ss:02d}"
            return f"{m:02d}:{ss:02d}"
        # ETA
        if finished>0 and total>0:
            predicted=elapsed*total/finished
            remaining=max(0.0,predicted-elapsed)
            pct_time=int((elapsed/predicted*100) if predicted>0 else 100)
        else:
            remaining=0.0; pct_time=0
        while i<len(s):
            if s[i]!="%": out.append(s[i]); i+=1; continue
            c=s[i+1]; i+=2
            if c=="%": out.append("%")
            elif c=="s": out.append(str(self.started))
            elif c=="t": out.append(str(total))
            elif c=="f": out.append(str(finished))
            elif c=="r": out.append(str(self.running))
            elif c=="u": out.append(str(max(0,total-self.started)))
            elif c=="p": out.append(f"{int(finished*100/total) if total else 100:3d}%")
            elif c=="P": out.append(f"{pct_time:3d}%")
            elif c=="e": out.append(f"{elapsed:.3f}")
            elif c=="E": out.append(f"{remaining:.3f}")
            elif c=="w": out.append(fmt_time_hms(elapsed))
            elif c=="W": out.append(fmt_time_hms(remaining))
            elif c=="o":
                out.append(f"{(finished/elapsed if elapsed>0 else 0):.1f}")
            elif c=="c":
                out.append(self.current_rate())
            else: out.append("")
        return "".join(out)
    def current_rate(self):
        # approximate: need parallelism+? Use window = parallelism from config if explicit else guess?
        # Reference: available after enough finishes. Implement a window of config.parallelism (capped)
        window=self.config.parallelism
        if window is None or window>1000000: window=guess_parallelism()
        if window<=1: return "?"
        if len(self.finish_times) < 2:
            return "?"
        # times are elapsed ms at finishes (including current before append? caller appends before format for finished)
        # Use last `window` intervals
        times=self.finish_times
        if len(times) <= window:
            # For j=2, reference shows ? for first 2 then value at 3rd. Require > window
            if len(times) <= window: return "?" if len(times)<=window and False else self._rate_from(times,window)
        return self._rate_from(times,window)
    def _rate_from(self,times,window):
        # mimic observed variability roughly: window / (now - time of finish window ago)
        if len(times)<2: return "?"
        idx=max(0,len(times)-1-window)
        span_ms=times[-1]-times[idx]
        if span_ms<=0: span_ms=1
        # If not enough history for j=3 second finish gave a value in reference; our simple gives value. Accept differences.
        return f"{window/(span_ms/1000.0):.1f}"
    def _desc(self,edge):
        if self.config.verbosity==1: # verbose
            return edge.get_command()
        desc=edge.get_description()
        if desc!="": return desc
        return edge.get_command()
    def _emit(self,data):
        out_write(data)
    def _emit_event(self, chunks, is_console_finished=False):
        # chunks: list of strings to output in order for a finished edge
        if self.console_running and not is_console_finished:
            self.buffered.append(chunks); return
        for ch in chunks: self._emit(ch)
        if is_console_finished:
            # flush buffered
            buf=self.buffered; self.buffered=[]
            for ev in buf:
                for ch in ev: self._emit(ch)
    def edge_started(self,edge):
        self.started+=1; self.running+=1
        is_console = (edge.pool is not None and getattr(edge.pool,'is_console',False))
        if self.config.verbosity==2: # quiet
            if is_console: self.console_running=True
            return
        text=self.format_status(edge)+self._desc(edge)
        if is_console:
            self.console_running=True
            if self.smart:
                line=elide_middle(text,get_terminal_width())
                self._emit_event(["\r"+line+"\x1b[K\n"], is_console_finished=False)
            else:
                # console start line is printed immediately, not buffered (it sets console mode)
                self._emit(text+"\n")
        elif self.smart:
            line=elide_middle(text,get_terminal_width())
            # if a console is running, smart lines are buffered by printer? In reference other edges' started prints are suppressed while console.
            if self.console_running:
                pass
            else:
                self._emit("\r"+line+"\x1b[K")
    def edge_finished(self,edge,success,output,exit_code):
        self.finished+=1
        self.finish_times.append(self.elapsed_ms())
        is_console = (edge.pool is not None and getattr(edge.pool,'is_console',False))
        # Build chunks
        chunks=[]
        already_printed_start=is_console and self.config.verbosity!=2
        if self.config.verbosity!=2 and not already_printed_start:
            text=self.format_status(edge)+self._desc(edge)
            if self.smart:
                line=elide_middle(text,get_terminal_width())
                chunks.append("\r"+line+"\x1b[K\n")
            else:
                chunks.append(text+"\n")
        if success:
            if output and not is_console:
                chunks.append(output if output.endswith("\n") or isinstance(output,bytes) and output.endswith(b"\n") else output+"\n")
        else:
            # FAILED block
            outs="".join(o.path+" " for o in edge.outputs)
            if self.smart:
                chunks.append(f"\x1b[31mFAILED: [code={exit_code}] \x1b[0m{outs}\n")
            else:
                chunks.append(f"FAILED: [code={exit_code}] {outs}\n")
            chunks.append(edge.get_command()+"\n")
            if output and not is_console:
                chunks.append(output if (isinstance(output,str) and output.endswith("\n")) else output+"\n")
        # running decrement after formatting (%r included this edge)
        self.running-=1
        if is_console:
            self.console_running=False
            self._emit_event(chunks, is_console_finished=True)
        else:
            self._emit_event(chunks, is_console_finished=False)
    def build_stopped(self,reason):
        line=f"ninja: build stopped: {reason}.\n"
        if self.console_running:
            self.buffered.append([line])
        else:
            self._emit(line)
    def no_work(self):
        if self.config.verbosity!=2:
            self._emit("ninja: no work to do.\n")

class BuildConfig:
    def __init__(self):
        self.verbosity=0 #0 normal,1 verbose,2 quiet
        self.dry_run=False
        self.parallelism=guess_parallelism()
        self.parallelism_explicit=False
        self.failures_allowed=1
        self.max_load=0.0
        self.input_file="build.ninja"
        self.working_dir=None

# ---------- Plan / Builder ----------
class RunningJob:
    pass

class Builder:
    def __init__(self,state,config,build_log,deps_log,manifest_parser,status,disk=None):
        self.state=state; self.config=config; self.build_log=build_log; self.deps_log=deps_log
        self.manifest_parser=manifest_parser; self.status=status
        self.scan=DependencyScan(state,build_log,deps_log,manifest_parser)
        self.wanted=set()  # edges to start
        self.pending=set() # dyndep want-to-finish edges
        self.finished_edges=set()
        self.failed_edges=set()
        self.ready=[] # heap entries
        self.edge_state={} # edge-> 'wanted','pending','ready','running','done','clean','failed'
        self.node_ready={}
        self.running_jobs=[]
        self.failures=0
        self.last_failure_code=1
        self.interrupted=False
        self.interrupt_code=130
        self.build_start_perf=time.perf_counter()
        self.status.reset_for_builder()
        self._total_added=False
        self._old_handlers={}
        self._install_signals()
        self.pool_counts={}
        # jobserver
        self.jobserver=None
        self.jobserver_mode_printed=False
        self._init_jobserver()
    # signals
    def _sig_handler(self,signum,frame):
        self.interrupted=True
    def _install_signals(self):
        try:
            for sig in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
                self._old_handlers[sig]=signal.getsignal(sig)
                signal.signal(sig, self._sig_handler)
        except Exception:
            pass
    def _restore_signals(self):
        try:
            for sig, h in self._old_handlers.items():
                signal.signal(sig,h)
        except Exception: pass
        self._cleanup_lock_file()
    def _cleanup_lock_file(self):
        # Remove .ninja_lock in builddir like reference builder cleanup (ignore errors) - only for real builders after targets collected
        try:
            bd=self.state.bindings.lookup_variable("builddir") if self.state else ""
            p=join_build_dir(bd,".ninja_lock")
            Disk.remove_file(p)
        except Exception:
            pass
    # jobserver init
    def _init_jobserver(self):
        if self.config.dry_run or self.config.parallelism_explicit:
            return
        makeflags=os.environ.get("MAKEFLAGS")
        if makeflags is None: return
        auth=None
        for word in makeflags.split():
            if word.startswith("--jobserver-auth="): auth=word[len("--jobserver-auth="):]
            elif word.startswith("--jobserver-fds="): auth=word[len("--jobserver-fds="):]
        if auth is None: return
        if auth.startswith("fifo:"):
            # Print mode detected with full MAKEFLAGS
            print_out(f"ninja: Jobserver mode detected: {makeflags}")
            fifopath=auth[len("fifo:"):]
            if fifopath=="":
                Error("Could not initialize jobserver: Empty fifo path"); return
            try:
                st=os.stat(fifopath)
            except OSError as e:
                Error(f"Could not initialize jobserver: Error opening fifo for reading: {e.strerror or str(e)}"); return
            if not stat.S_ISFIFO(st.st_mode):
                Error(f"Could not initialize jobserver: Not a fifo path: {fifopath}"); return
            try:
                rfd=os.open(fifopath, os.O_RDWR|os.O_NONBLOCK)
                wfd=os.open(fifopath, os.O_WRONLY|os.O_NONBLOCK)
            except OSError as e:
                Error(f"Could not initialize jobserver: Error opening fifo for reading: {e.strerror or str(e)}"); return
            self.jobserver={"rfd":rfd,"wfd":wfd,"tokens":[]} # tokens list of bytes acquired 'in hand' beyond implicit? We track per job
            self.jobserver_acquired=[] # stack of token bytes held for running extra jobs
        elif "," in auth:
            Warning(f"Ignoring jobserver: Pipe-based protocol is not supported! [{makeflags}]")
        else:
            Warning(f"Ignoring jobserver: Semaphore mode is not supported on Posix! [{makeflags}]")
    def _jobserver_acquire(self):
        # return token byte or None if none available, or '' for implicit handled by caller
        if not self.jobserver: return None
        try:
            data=os.read(self.jobserver["rfd"],1)
            if data: return data
            return None
        except BlockingIOError:
            return None
        except OSError:
            return None
    def _jobserver_release(self,token):
        if not self.jobserver or not token: return
        try: os.write(self.jobserver["wfd"],token)
        except OSError: pass
    def _close_jobserver(self):
        if self.jobserver:
            for k in ("rfd","wfd"):
                try: os.close(self.jobserver[k])
                except Exception: pass
            self.jobserver=None
    # target adding
    def add_target(self,node, parent_node=None, top_level=False):
        # returns None or raises NinjaError missing/cycle etc via scan done by caller
        edge=node.in_edge
        if edge is None:
            return
        self._add_edge(edge, via_node=node)
    def _is_node_ready_initial(self,node):
        if node.in_edge is None: return True
        if id(node.in_edge) in [id(e) for e in self.wanted]: return False
        if node.in_edge in self.wanted or node.in_edge in self.pending: return False
        return True
    def _add_edge(self,edge, via_node):
        if edge in self.edge_state:
            return
        # determine wanted vs clean/pending
        any_dirty=False
        for o in edge.outputs:
            if o.dirty: any_dirty=True
        is_pending = edge.dyndep_node is not None and not edge.dyndep_loaded
        if not any_dirty and not is_pending:
            self.edge_state[edge]="clean"
            for o in edge.outputs: self.node_ready[id(o)]=True
            return
        # check missing inputs first (in order) and recurse
        # First gather prerequisites (static + dep_nodes)
        prereqs=list(edge.inputs)+list(edge.dep_nodes)
        for inp in prereqs:
            if inp.in_edge is None and not inp.dep_loader_phantom:
                inp.stat_if_necessary()
                if inp.mtime==0:
                    raise NinjaError(f"'{inp.path}', needed by '{via_node.path}', missing and no known rule to make it")
        if is_pending and not any_dirty:
            self.edge_state[edge]="pending"; self.pending.add(edge)
        else:
            self.edge_state[edge]="wanted"; self.wanted.add(edge)
        for inp in prereqs:
            if inp.in_edge is not None:
                self._add_edge(inp.in_edge, via_node=inp)
    def compute_priorities(self):
        with MetricTimer(g_metrics,"ComputeCriticalPath"):
            # priority = longest downstream chain of wanted/pending edges
            memo={}
            visiting=set()
            def prio(edge):
                if id(edge) in memo: return memo[id(edge)]
                if id(edge) in visiting: return 0
                visiting.add(id(edge))
                best=0
                for o in edge.outputs:
