    rsp=edge.get_unescaped_binding("rspfile")
    if not rsp: return command
    content=edge.get_binding("rspfile_content",True)
    marker="@"+rsp
    # replace marker when at start or preceded by space or double quote, and followed by space/quote/end
    res=[]; i=0
