        # node-based existence checked by caller for main outputs; for dep/rsp we check existence here
        try:
            st=os.stat(path)
        except OSError:
            return
        if self.verbose or self.config.dry_run:
            print_out(f"Remove {path}")
        if self.config.dry_run:
            self.count+=1; return
