        if id(node) in self.cleaned: return
        self.cleaned.add(id(node))
        node.reset_stat()
        if node.stat_if_necessary()!=0:
            self.remove_path(node.path)
        edge=node.in_edge
        if edge is not None:
            depfile=edge.get_unescaped_binding("depfile")
            if depfile: self.remove_path(depfile)
            rsp=edge.get_unescaped_binding("rspfile")
            if rsp: self.remove_path(rsp)
