        # iterative recursion with cleaned guard at node level; recursion to inputs
        # To avoid infinite cycles, track visited target nodes locally
        def rec(n,seen):
            if id(n) in seen: return
            seen.add(id(n))
            self.clean_node(n)
            e=n.in_edge
            if e is not None:
                for inp in e.inputs:
                    rec(inp,seen)
