# ---------- getopt via libc (glibc) ----------
class Getopt:
    def __init__(self,argv,optstring,long_opts=None):
        self.argv=list(argv)
        self.optstring=optstring
        self.long_opts=long_opts or []
        self._init_libc()
    def _init_libc(self):
        import ctypes
        self.ctypes=ctypes
        self.libc=ctypes.CDLL("libc.so.6")
        class COption(ctypes.Structure):
            _fields_=[("name",ctypes.c_char_p),("has_arg",ctypes.c_int),("flag",ctypes.POINTER(ctypes.c_int)),("val",ctypes.c_int)]
        self.COption=COption
        opts=[]
        for name,has,val in self.long_opts:
            opts.append(COption(os.fsencode(name),has,None,val))
        opts.append(COption(None,0,None,0))
        self.c_opts=(COption*len(opts))(*opts)
        self.argc=len(self.argv)
        arr=(ctypes.c_char_p*(self.argc+1))()
        self._encoded=[]
        for i,a in enumerate(self.argv):
            b=ctypes.create_string_buffer(os.fsencode(a))
            self._encoded.append(b)
            arr[i]=ctypes.cast(b,ctypes.c_char_p)
        arr[self.argc]=None
        self.c_argv=arr
        self.libc.getopt_long.restype=ctypes.c_int
        self.libc.getopt_long.argtypes=[ctypes.c_int, ctypes.POINTER(ctypes.c_char_p), ctypes.c_char_p, ctypes.POINTER(COption), ctypes.POINTER(ctypes.c_int)]
        self.libc.getopt.restype=ctypes.c_int
        self.libc.getopt.argtypes=[ctypes.c_int, ctypes.POINTER(ctypes.c_char_p), ctypes.c_char_p]
        ctypes.c_int.in_dll(self.libc,"optind").value=0
        ctypes.c_int.in_dll(self.libc,"opterr").value=1
    @property
    def optind(self):
        return self.ctypes.c_int.in_dll(self.libc,"optind").value
    @property
    def optarg(self):
        v=self.ctypes.c_char_p.in_dll(self.libc,"optarg").value
        return os.fsdecode(v) if v is not None else None
    def next(self):
        if self.long_opts:
            r=self.libc.getopt_long(self.argc,self.c_argv,os.fsencode(self.optstring),self.c_opts,None)
        else:
            r=self.libc.getopt(self.argc,self.c_argv,os.fsencode(self.optstring))
        return r
    def remaining(self):
        res=[]
        for i in range(self.optind,self.argc):
            v=self.c_argv[i]
            res.append(os.fsdecode(v) if v is not None else "")
        return res

