def tool_clean(state,args,config,manifest_parser,build_log,deps_log):
    usage=("usage: ninja -t clean [options] [targets]\n\n"
           "options:\n"
           "  -g     also clean files marked as ninja generator output\n"
           "  -r     interpret targets as a list of rules to clean instead\n")
    go=Getopt(["clean"]+args,"grh")
    clean_generated=False; rules_mode=False
    while True:
        opt=go.next()
        if opt==-1: break
        c=chr(opt) if 0<opt<256 else "?"
        if c=="g": clean_generated=True
        elif c=="r": rules_mode=True
        elif c=="h" or c=="?": out_write(usage); return 1
        else: out_write(usage); return 1
    rest=go.remaining()
    cleaner=Cleaner(state,config)
    result=0
    try:
        if rules_mode:
            if not rest:
                Error("expected a rule to clean"); cleaner.finish(); return 1
            for rname in rest:
                rule=state.bindings.lookup_rule(rname)
                if rule is None:
                    Error(f"unknown rule '{rname}'"); result=1; break
                if cleaner.verbose: print_out(f"Rule {rname}")
                for edge in state.edges:
                    if edge.rule is rule:
                        for o in edge.outputs: cleaner.clean_node(o)
        elif rest:
            for a in rest:
                try:
                    node=collect_target(state,a)
                except NinjaError as e:
                    Error(e.msg); result=1; break
                if cleaner.verbose: print_out(f"Target {node.path}")
                cleaner.clean_target(node)
        else:
            cleaner.clean_all(clean_generated)
        if cleaner.status!=0: result=cleaner.status
    finally:
        # Cleaner.finish prints footer; if we returned early for no-rule case above we already called.
        pass
    # Avoid double finish for early return path: tracked by result? Simpler: if rules_mode and not rest handled return above.
    cleaner.finish()
    return result

