        # dependency order list across targets with common visited
        visited_edges=set(); result=[]; seen=set()
        def visit(node):
            e=node.in_edge
            if e is None or id(e) in visited_edges: return
            visited_edges.add(id(e))
            for inp in e.inputs:
                visit(inp)
                if id(inp) not in seen:
                    seen.add(id(inp)); result.append(inp)
        for t in targets: visit(t)
        paths=[n.path for n in result]
        if not deporder:
            paths=sorted(paths)
        term="\x00" if print0 else "\n"
        for p in paths:
            s=p if noesc else shell_escape(p)
            out_write(encode_bytes(s)+encode_bytes(term))
        return 0
    else:
        usage=("Usage '-t multi-inputs [options] [targets]\n\n"
               "Print one or more sets of inputs required to build targets, sorted in dependency order.\n"
               "The tool works like inputs tool but with addition of the target for each line.\n"
               "The output will be a series of lines with the following elements:\n"
               "<target> <delimiter> <input> <terminator>\n"
               "Note that a given input may appear for several targets if it is used by more than one targets.\n"
               "Options:\n"
               "  -h, --help                   Print this message.\n"
               "  -d  --delimiter=DELIM        Use DELIM instead of TAB for field delimiter.\n"
               "  -0, --print0                 Use \\0, instead of \\n as a line terminator.\n")
        go=Getopt(["multi-inputs"]+args,"h0d:",[("help",0,ord('h')),("print0",0,ord('0')),("delimiter",1,ord('d'))])
        print0=False; delim="\t"
        while True:
            opt=go.next()
            if opt==-1: break
            c=chr(opt) if 0<opt<256 else "?"
            if c=="0": print0=True
            elif c=="d": delim=go.optarg
            elif c=="h" or c=="?": out_write(usage); return 1
            else: out_write(usage); return 1
        rest=go.remaining()
        try: targets=collect_targets(state,rest)
        except NinjaError as e: Error(e.msg); return 1
        term="\x00" if print0 else "\n"
        for t in targets:
            for inp in traverse_inputs_for(t):
                out_write(encode_bytes(t.path+delim+inp.path)+encode_bytes(term))
        return 0

def tool_deps(state,args,config,manifest_parser,build_log,deps_log):
    if deps_log is None: return 0
    if args:
