def tool_missingdeps(state,args,config,manifest_parser,build_log,deps_log):
    try: targets=collect_targets(state,args)
    except NinjaError as e: Error(e.msg); return 1
    visited=set(); processed=0; ordered=[]
    def visit(node):
        nonlocal processed
        if id(node) in visited: return
        visited.add(id(node))
        e=node.in_edge
        if e is None: return
        processed+=1; ordered.append(node)
        for inp in e.inputs: visit(inp)
    for t in targets: visit(t)
    # transitive static dependencies per node cached
    trans_cache={}
    def transitive(node):
        if id(node) in trans_cache: return trans_cache[id(node)]
        res=set(); stack=[]
        if node.in_edge: stack=list(node.in_edge.inputs)
        while stack:
            n=stack.pop()
            if id(n) in res: continue
            res.add(id(n))
            if n.in_edge: stack.extend(n.in_edge.inputs)
        trans_cache[id(node)]=res; return res
    missing=[]; affected=set(); distinct_gen=set(); distinct_rules=set()
    for node in ordered:
        if deps_log is None: break
        entry=deps_log.get_deps(node)
        if entry is None: continue
        trans=transitive(node)
        for dep in entry.deps:
            ge=dep.in_edge
            if ge is not None and not ge.is_phony():
                if id(dep) not in trans:
                    missing.append((node,dep,ge.rule.name)); affected.add(id(node)); distinct_gen.add(id(dep)); distinct_rules.add(ge.rule.name)
    for node,dep,rulename in missing:
        print_out(f"Missing dep: {node.path} uses {dep.path} (generated by {rulename})")
    print_out(f"Processed {processed} nodes.")
    if missing:
        print_out(f"Error: There are {len(missing)} missing dependency paths.")
        print_out(f"{len(affected)} targets had depfile dependencies on {len(distinct_gen)} distinct generated inputs (from {len(distinct_rules)} rules)  without a non-depfile dep path to the generator.")
        print_out("There might be build flakiness if any of the targets listed above are built alone, or not late enough, in a clean output directory.")
        return 3
    else:
        print_out("No missing dependencies on generated files found.")
        return 0

def tool_graph(state,args,config,manifest_parser,build_log,deps_log):
    try: targets=collect_targets(state,args)
    except NinjaError as e: Error(e.msg); return 1
    print_out("digraph ninja {")
    print_out("rankdir=\"LR\"")
    print_out("node [fontsize=10, shape=box, height=0.25]")
    print_out("edge [fontsize=10]")
    visited=set()
    def nid(obj): return hex(id(obj))
    sys.setrecursionlimit(100000)
    def print_node(node):
        if id(node) in visited: return
        visited.add(id(node))
        print_out(f"\"{nid(node)}\" [label=\"{node.path}\"]")
        edge=node.in_edge
        if edge is None: return
        if len(edge.inputs)==1 and len(edge.outputs)==1:
            inp=edge.inputs[0]
            print_out(f"\"{nid(inp)}\" -> \"{nid(node)}\" [label=\" {edge.rule.name}\"]")
            print_node(inp)
        else:
            eid=nid(edge)
            print_out(f"\"{eid}\" [label=\"{edge.rule.name}\", shape=ellipse]")
            for o in edge.outputs:
                print_out(f"\"{eid}\" -> \"{nid(o)}\"")
            order_inputs=edge.order_only_inputs()
            order_ids=set(id(x) for x in order_inputs)
            # determine order-only by position
            for idx,inp in enumerate(edge.inputs):
                is_order = idx >= len(edge.inputs)-edge.order_only_in if edge.order_only_in else False
                if is_order:
                    print_out(f"\"{nid(inp)}\" -> \"{eid}\" [arrowhead=none style=dotted]")
                else:
                    print_out(f"\"{nid(inp)}\" -> \"{eid}\" [arrowhead=none]")
            for inp in edge.inputs:
                print_node(inp)
    for t in targets: print_node(t)
    print_out("}")
    return 0

def tool_query(state,args,config,manifest_parser,build_log,deps_log):
    if not args:
        Error("expected a target to query"); return 1
    scan=DependencyScan(state,build_log,deps_log,manifest_parser)
    for a in args:
        try:
            node=collect_target(state,a)
        except NinjaError as e:
            Error(e.msg); return 1
        validations=[]
        try:
            scan.recompute_dirty(node,validations)
        except NinjaError as e:
            # Warning adds newline to msg (msg may end without newline)
            err_write(f"ninja: warning: {e.msg}\n")
        print_out(f"{node.path}:")
        edge=node.in_edge
        if edge is not None:
            print_out(f"  input: {edge.rule.name}")
            for inp in edge.explicit_inputs(): print_out(f"    {inp.path}")
            for inp in edge.implicit_inputs(): print_out(f"    | {inp.path}")
            for inp in edge.order_only_inputs(): print_out(f"    || {inp.path}")
            if edge.validations:
                print_out("  validations:")
                for v in edge.validations: print_out(f"    {v.path}")
        print_out("  outputs:")
        for oe in node.out_edges:
            for o in oe.outputs: print_out(f"    {o.path}")
        if node.validation_out_edges:
            print_out("  validation for:")
            for oe in node.validation_out_edges:
                for o in oe.outputs: print_out(f"    {o.path}")
    return 0

def tool_targets(state,args,config,manifest_parser,build_log,deps_log):
    if not args:
        mode="depth"; depth=1
        roots=state.root_nodes()
        if not roots:
            Error("could not determine root nodes of build graph"); return 1
        for r in roots:
            print_out(f"{r.path}: {r.in_edge.rule.name}")
        return 0
    mode=args[0]
    if mode=="rule":
        if len(args)>=2:
            rulename=args[1]
            outs=set()
            for e in state.edges:
                if e.rule.name==rulename:
                    for o in e.outputs: outs.add(o.path)
            for p in sorted(outs): print_out(p)
            return 0
        else:
            for e in state.edges:
                for inp in e.inputs:
                    if inp.in_edge is None: print_out(inp.path)
            return 0
    elif mode=="depth":
        depth=1
        if len(args)>=2:
            depth=c_atoi(args[1])
        roots=state.root_nodes()
        if not roots:
            Error("could not determine root nodes of build graph"); return 1
        sys.setrecursionlimit(100000)
        def rec(node,depth,indent):
            if node.in_edge is not None:
                print_out(f"{indent}{node.path}: {node.in_edge.rule.name}")
            else:
                print_out(f"{indent}{node.path}")
            if depth==1: return
            e=node.in_edge
            if e is not None:
                for inp in e.inputs:
                    rec(inp,depth-1,indent+"  ")
        for r in roots: rec(r,depth,"")
        return 0
    elif mode=="all":
        for e in state.edges:
            for o in e.outputs: print_out(f"{o.path}: {e.rule.name}")
        return 0
    else:
        cand=closest_word(mode,["all","rule","depth"])
        if cand: Error(f"unknown target tool mode '{mode}', did you mean '{cand}'?")
        else: Error(f"unknown target tool mode '{mode}'")
        return 1

def tool_compdb(state,args,config,manifest_parser,build_log,deps_log):
    usage=("usage: ninja -t compdb [options] [rules]\n\n"
           "options:\n"
           "  -x     expand @rspfile style response file invocations\n")
    go=Getopt(["compdb"]+args,"hx"); expand=False
    while True:
        opt=go.next()
        if opt==-1: break
        c=chr(opt) if 0<opt<256 else "?"
        if c=="x": expand=True
        elif c=="h" or c=="?": out_write(usage); return 1
        else: out_write(usage); return 1
    rest=go.remaining()
    edges=[]
    if not rest:
        edges=list(state.edges)
    else:
        rules=[]
        for rn in rest:
            r=state.bindings.lookup_rule(rn)
            if r is not None: rules.append(r)
        for e in state.edges:
            for r in rules:
                if e.rule is r: edges.append(e)
    out_write(compdb_entries(edges,expand))
    return 0

