    print_out(f"Processed {processed} nodes.")
    if missing:
        print_out(f"Error: There are {len(missing)} missing dependency paths.")
        print_out(f"{len(affected)} targets had depfile dependencies on {len(distinct_gen)} distinct generated inputs (from {len(distinct_rules)} rules)  without a non-depfile dep path to the generator.")
        print_out("There might be build flakiness if any of the targets listed above are built alone, or not late enough, in a clean output directory.")
        return 3
    else:
