        if c=="h" or c=="?": out_write(usage); return 1
        else: out_write(usage); return 1
    rest=go.remaining()
    log=BuildLog()
    log.load(".ninja_log")
    if log.load_status=="error":
        # reference ignores? For log directory, load may treat empty and recompact fails on unlink.
        # Continue with empty entries.
        pass
    if log.load_status=="notfound":
        return 0
    if log.load_status in ("old","new"):
        Disk.remove_file(".ninja_log")
        return 0
    wanted=set(rest)
    for entry in log.entries.values():
        if wanted and entry.output not in wanted: continue
        entry.mtime=Disk.stat(entry.output)
    ok,err=log.recompact(".ninja_log", ".restat")
    if not ok:
        Error(f"failed recompaction: {err}"); return 1
    return 0

