        go=Getopt(["inputs"]+args,"h0Ed",[("help",0,ord('h')),("print0",0,ord('0')),("no-shell-escape",0,ord('E')),("dependency-order",0,ord('d'))])
        print0=False; noesc=False; deporder=False
        while True:
