def tool_targets(state,args,config,manifest_parser,build_log,deps_log):
    if not args:
        mode="depth"; depth=1
        roots=state.root_nodes()
        if not roots:
            Error("could not determine root nodes of build graph"); return 1
        for r in roots:
            print_out(f"{r.path}: {r.in_edge.rule.name}")
        return 0
    mode=args[0]
    if mode=="rule":
        if len(args)>=2:
            rulename=args[1]
            outs=set()
            for e in state.edges:
                if e.rule.name==rulename:
                    for o in e.outputs: outs.add(o.path)
            for p in sorted(outs): print_out(p)
            return 0
        else:
            for e in state.edges:
                for inp in e.inputs:
                    if inp.in_edge is None: print_out(inp.path)
            return 0
    elif mode=="depth":
        depth=1
        if len(args)>=2:
            depth=c_atoi(args[1])
        roots=state.root_nodes()
        if not roots:
            Error("could not determine root nodes of build graph"); return 1
        sys.setrecursionlimit(100000)
        def rec(node,depth,indent):
            if node.in_edge is not None:
                print_out(f"{indent}{node.path}: {node.in_edge.rule.name}")
            else:
                print_out(f"{indent}{node.path}")
            if depth==1: return
            e=node.in_edge
            if e is not None:
                for inp in e.inputs:
                    rec(inp,depth-1,indent+"  ")
        for r in roots: rec(r,depth,"")
        return 0
    elif mode=="all":
        for e in state.edges:
            for o in e.outputs: print_out(f"{o.path}: {e.rule.name}")
        return 0
    else:
        cand=closest_word(mode,["all","rule","depth"])
        if cand: Error(f"unknown target tool mode '{mode}', did you mean '{cand}'?")
        else: Error(f"unknown target tool mode '{mode}'")
        return 1

