    usage=("usage: ninja -t compdb [options] [rules]\n\n"
           "options:\n"
           "  -x     expand @rspfile style response file invocations\n")
    go=Getopt(["compdb"]+args,"hx"); expand=False
    while True:
        opt=go.next()
        if opt==-1: break
        c=chr(opt) if 0<opt<256 else "?"
        if c=="x": expand=True
        elif c=="h" or c=="?": out_write(usage); return 1
        else: out_write(usage); return 1
    rest=go.remaining()
    edges=[]
    if not rest:
        edges=list(state.edges)
    else:
        rules=[]
        for rn in rest:
            r=state.bindings.lookup_rule(rn)
            if r is not None: rules.append(r)
        for e in state.edges:
            for r in rules:
                if e.rule is r: edges.append(e)
    out_write(compdb_entries(edges,expand))
    return 0

def tool_compdb_targets(state,args,config,manifest_parser,build_log,deps_log):
    usage=("usage: ninja -t compdb [-hx] target [targets]\n\n"
           "options:\n"
           "  -h     display this help message\n"
           "  -x     expand @rspfile style response file invocations\n")
    go=Getopt(["compdb-targets"]+args,"hx"); expand=False
    while True:
        opt=go.next()
        if opt==-1: break
        c=chr(opt) if 0<opt<256 else "?"
        if c=="x": expand=True
        elif c=="h" or c=="?": out_write(usage); return 1
        else: out_write(usage); return 1
    rest=go.remaining()
    if not rest:
        out_write(usage)
        err_write("ninja: error: compdb-targets expects the name of at least one target\n")
        return 1
    targets=[]
    for a in rest:
        try:
            node=collect_target(state,a)
        except NinjaError as e:
            Fatal(e.msg)
        if node.in_edge is None:
            Fatal(f"'{node.path}' is not a target (i.e. it is not an output of any `build` statement)")
        targets.append(node)
    edges=traverse_edges_postorder(targets)
    out_write(compdb_entries(edges,expand))
    return 0

def tool_recompact(state,args,config,manifest_parser,build_log,deps_log):
    # args ignored
    if deps_log is None: return 0
    if deps_log.load_status=="notfound":
        return 0
    bd=state.bindings.lookup_variable("builddir")
    deps_path=join_build_dir(bd,".ninja_deps")
    live=set()
    for n in state.nodes:
        if n.in_edge is not None: live.add(n.path)
    ok,err=deps_log.recompact(deps_path,live)
    if not ok:
        Error(f"failed recompaction: {err}"); return 1
    return 0

