def rebuild_manifest(state,parser,config,build_log,deps_log,status):
    # returns (rebuilt_bool, ran) or raises NinjaError with reason for main wrapper
    path=canonicalize_path(config.input_file)
    node=state.lookup_node(path)
    if node is None or node.in_edge is None:
        return (False,0)
    builder=Builder(state,config,build_log,deps_log,parser,status)
    validations=[]
    try:
        builder.scan.recompute_dirty(node,validations)
        if node.in_edge is not None:
            builder._add_edge(node.in_edge, via_node=node)
        for v in validations:
            builder.scan.recompute_dirty(v,[])
            if v.in_edge is not None:
                try: builder._add_edge(v.in_edge, via_node=v)
                except NinjaError: pass
    except NinjaError as e:
        raise
    builder.prepare()
    if not builder.wanted and not builder.pending:
        # clean
        builder._restore_signals(); builder._close_jobserver()
        return (False,0)
    code,reason,ran=builder.build()
    if code!=0:
        if reason is None: reason="subcommand failed"
        if reason=="": reason=""
        raise NinjaError(reason)
    return (ran>0,ran)

def run_build(config,targets_arg):
    status=BuildStatus(config)
    cycle=1
    stats_state=None
    try:
        while True:
            try:
                state,parser=load_manifest(config)
            except ParseError as e:
                Error(e.msg); return 1
            except NinjaError as e:
                Error(e.msg); return 1
            stats_state=state
            build_log,deps_log,ok=open_logs(state,config)
            if not ok:
                dump_stats(state); return 1
            # rebuild manifest
            try:
                rebuilt,ran=rebuild_manifest(state,parser,config,build_log,deps_log,status)
            except NinjaError as e:
                # Close logs
                if build_log: build_log.close()
                if deps_log: deps_log.close()
                if e.msg=="":
                    # Stop message already printed as 'ninja: build stopped: .' by builder path? Our builder returns reason "" and caller in rebuild didn't print stopped.
                    status.build_stopped("")
                Error(f"rebuilding '{config.input_file}': {e.msg}" if e.msg else f"rebuilding '{config.input_file}': ")
                # Reference for subcommand failed has exactly that Error (no build stopped line). For non-subcommand errors, also this wrapper.
                # If we already printed build_stopped for empty, above duplicates somewhat but rare.
                dump_stats(state); return 1
            if rebuilt:
                if build_log: build_log.close()
                if deps_log: deps_log.close()
                if config.dry_run:
                    dump_stats(state); return 0
                cycle+=1
                if cycle>100:
                    Error(f"manifest '{config.input_file}' still dirty after 100 tries, perhaps system time is not set")
                    dump_stats(state); return 1
                continue
            # collect targets
            try:
                targets=collect_targets(state,targets_arg)
            except NinjaError as e:
                Error(e.msg)
                if build_log: build_log.close()
                if deps_log: deps_log.close()
                dump_stats(state); return 1
            builder=Builder(state,config,build_log,deps_log,parser,status)
            try:
                validations=[]
                # Recompute and add targets
                for t in targets:
                    builder.scan.recompute_dirty(t,validations)
                    if t.in_edge is None:
                        t.stat_if_necessary()
                        if t.mtime==0:
                            raise NinjaError(f"'{t.path}' missing and no known rule to make it")
                    else:
                        builder._add_edge(t.in_edge, via_node=t)
