                seen_val=set(); idx=0
                while idx<len(validations):
                    v=validations[idx]; idx+=1
                    if id(v) in seen_val: continue
                    seen_val.add(id(v))
                    newvals=[]
                    builder.scan.recompute_dirty(v,newvals)
                    for nv in newvals:
                        if nv not in validations: validations.append(nv)
                    if v.in_edge is not None:
                        builder._add_edge(v.in_edge, via_node=v)
            except NinjaError as e:
                Error(e.msg)
                # builder cleanup signals/lock
                builder._restore_signals(); builder._close_jobserver()
                if build_log: build_log.close()
                if deps_log: deps_log.close()
                dump_stats(state); return 1
            builder.prepare()
            if not builder.wanted and not builder.pending:
                status.no_work()
                builder._restore_signals(); builder._close_jobserver()
                if build_log: build_log.close()
                if deps_log: deps_log.close()
                dump_stats(state); return 0
            code,reason,ran=builder.build()
            if build_log: build_log.close()
            if deps_log: deps_log.close()
            if code!=0:
                if reason is not None:
                    status.build_stopped(reason)
                dump_stats(state); return code if code<=255 else code
            dump_stats(state); return 0
    finally:
        pass

def run_tool(tool_name,tool_args,config):
    if tool_name=="restat":
        return tool_restat(tool_args,config)
    # load manifest
    try:
        state,parser=load_manifest(config)
    except ParseError as e:
        Error(e.msg); return 1
    except NinjaError as e:
        Error(e.msg); return 1
    build_log=None; deps_log=None
    if tool_name in TOOLS_AFTER_LOGS:
        build_log,deps_log,ok=open_logs(state,config)
        if not ok: return 1
    try:
        if tool_name=="inputs":
            return tool_inputs(state,tool_args,config,parser,build_log,deps_log,multi=False)
        if tool_name=="multi-inputs":
            return tool_inputs(state,tool_args,config,parser,build_log,deps_log,multi=True)
        fn=TOOL_FUNCS.get(tool_name)
        if fn is None:
            Fatal(f"unknown tool '{tool_name}'")
        return fn(state,tool_args,config,parser,build_log,deps_log)
    finally:
        if build_log: build_log.close()
        if deps_log: deps_log.close()

