import struct
mask=(1<<64)-1;m=0xc6a4a7935bd1e995;r=47
def final(h):
 h ^=h>>r;h=h*m&mask;h ^=h>>r;return h
def invfinal(h):
 def unxor(y):
  x=y
  for i in range(3):x=y^(x>>r)
  return x
 h=unxor(h);h=h*pow(m,-1,1<<64)&mask;h=unxor(h);return h
seed=invfinal(0x5a6ef77074ebc84b)
def H(data,mode):
 if mode==0:h=seed
 elif mode==1:h=seed ^ len(data)
 elif mode==2:h=(seed+len(data))&mask
 elif mode==3:h=seed ^ ((len(data)*m)&mask)
 elif mode==4:h=(seed + len(data)*m)&mask
 elif mode==5:h=(seed* m ^ len(data))&mask
 nb=len(data)//8
 for i in range(nb):
  k=struct.unpack_from('<Q',data,i*8)[0];k=k*m&mask;k ^=k>>r;k=k*m&mask;h ^=k;h=h*m&mask
 rem=data[nb*8:]
 for i,c in enumerate(rem):h ^=c<<(8*i)
 if rem:h=h*m&mask
 return final(h)
